create temporary table expected_science_cards on commit drop as
select * from jsonb_populate_recordset(null::public.cards, $release$[{"id":"biology-jo-depth-001","deck_id":"biology-jo","kind":"choice","topic":"심화 · 가닥 방향·전사·RNA 가공","badge":"조용민T · 심화","question":"DNA 주형 가닥이 3′-TAC GGA ATT-5′다. 상보적으로 전사한 mRNA는?","passage":null,"answer":"5′-AUG CCU UAA-3′","wrong":["5′-UAC GGA AUU-3′","3′-AUG CCU UAA-5′","5′-ATG CCT TAA-3′"],"criteria":[],"explanation":"주형 DNA에 상보적이며 역평행으로 RNA가 합성된다. T에 A, A에 U, C에 G, G에 C를 대응시키고 5′→3′로 쓴다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":38},{"id":"biology-jo-depth-002","deck_id":"biology-jo","kind":"choice","topic":"심화 · 가닥 방향·전사·RNA 가공","badge":"조용민T · 심화","question":"DNA 암호화 가닥이 5′-ATG CCT TAA-3′다. 이 구간의 mRNA는?","passage":null,"answer":"5′-AUG CCU UAA-3′","wrong":["5′-ATG CCT TAA-3′","5′-UAC GGA AUU-3′","3′-AUG CCU UAA-5′"],"criteria":[],"explanation":"암호화 가닥과 mRNA는 같은 5′→3′ 방향에서 T/U 차이를 제외하면 같은 서열이다. 주형 가닥과 혼동하지 않는다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":39},{"id":"biology-jo-depth-003","deck_id":"biology-jo","kind":"choice","topic":"심화 · 가닥 방향·전사·RNA 가공","badge":"조용민T · 심화","question":"RNA 중합효소가 주형 DNA를 읽는 방향과 RNA를 합성하는 방향은?","passage":null,"answer":"3′→5′ 읽기·5′→3′ 합성","wrong":["둘 다 3′→5′","둘 다 5′→3′","5′→3′ 읽기·3′→5′ 합성"],"criteria":[],"explanation":"RNA의 새 뉴클레오타이드는 3′ 말단에 연결되므로 합성 방향은 5′→3′다. 주형을 읽는 방향은 반대다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":40},{"id":"biology-jo-depth-004","deck_id":"biology-jo","kind":"choice","topic":"심화 · 가닥 방향·전사·RNA 가공","badge":"조용민T · 심화","question":"pre-mRNA가 엑손 E1-인트론 I1-엑손 E2로 구성된다. 스플라이싱 후 연결은?","passage":null,"answer":"E1-E2","wrong":["I1-E1-E2","E1-I1","I1만 남음"],"criteria":[],"explanation":"스플라이싱은 인트론을 제거하고 엑손을 연결한다. 엑손을 제거하는 과정이나 DNA 염색체의 결실과 구별한다.","source_label":"조용민T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":41},{"id":"biology-jo-depth-005","deck_id":"biology-jo","kind":"choice","topic":"심화 · 가닥 방향·전사·RNA 가공","badge":"조용민T · 심화","question":"진핵 mRNA의 캡과 폴리 A 꼬리 기능에 대한 옳은 설명은?","passage":null,"answer":"안정성·수송·번역에 기여한다","wrong":["모든 코돈을 아데닌으로 바꾼다","DNA 주형의 인트론을 자른다","아미노산을 직접 운반한다"],"criteria":[],"explanation":"5′ 캡과 3′ 폴리 A 꼬리는 RNA 안정성과 수송·번역 효율 등에 기여한다. 아미노산 운반은 tRNA의 기능이다.","source_label":"조용민T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":42},{"id":"biology-jo-depth-006","deck_id":"biology-jo","kind":"choice","topic":"심화 · 가닥 방향·전사·RNA 가공","badge":"조용민T · 심화","question":"스플라이싱 복합체의 snRNA와 리보솜 rRNA를 구별한 것은?","passage":null,"answer":"snRNA는 가공·rRNA는 번역에 관여","wrong":["둘 다 반드시 단백질로 번역","둘 다 아미노산만 운반","snRNA는 DNA 복제·rRNA는 가공"],"criteria":[],"explanation":"snRNA는 스플라이싱에 관여하고 rRNA는 리보솜 구성과 펩타이드 결합 형성에 기여한다. 모든 RNA가 번역되는 것은 아니다.","source_label":"조용민T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":43},{"id":"biology-jo-depth-007","deck_id":"biology-jo","kind":"choice","topic":"심화 · 가닥 방향·전사·RNA 가공","badge":"조용민T · 심화","question":"핵이 있는 세포에서 전사한 RNA가 바로 번역되기 어려운 이유는?","passage":null,"answer":"전사·가공과 번역 장소가 구분된다","wrong":["RNA에는 코돈이 없다","세포질에 tRNA가 없다","리보솜이 DNA를 직접 읽는다"],"criteria":[],"explanation":"진핵세포에서 전사와 RNA 가공은 핵, 번역은 주로 세포질의 리보솜에서 진행된다. 핵막이 없는 원핵과 구별한다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":44},{"id":"biology-jo-depth-008","deck_id":"biology-jo","kind":"choice","topic":"심화 · 가닥 방향·전사·RNA 가공","badge":"조용민T · 심화","question":"RNA 주형으로 DNA가 합성됐다. 보통의 전사와 구별되는 정보 흐름은?","passage":null,"answer":"역전사","wrong":["번역","스플라이싱","독립 분리"],"criteria":[],"explanation":"역전사는 RNA→DNA의 정보 흐름이다. 보통의 전사 DNA→RNA 및 번역 RNA→단백질과 구별한다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":45},{"id":"biology-jo-depth-009","deck_id":"biology-jo","kind":"choice","topic":"심화 · 번역 단계와 코돈 계산","badge":"조용민T · 심화","question":"mRNA 5′-AUG GCU UUU UGA-3′를 첫 AUG에서 번역한다. 아미노산과 펩타이드 결합 수는?","passage":null,"answer":"3개·2개","wrong":["4개·3개","3개·3개","2개·1개"],"criteria":[],"explanation":"AUG·GCU·UUU는 각각 아미노산을 지정하지만 UGA는 종결 코돈이다. 선형 사슬 3개 아미노산의 펩타이드 결합은 2개다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":46},{"id":"biology-jo-depth-010","deck_id":"biology-jo","kind":"choice","topic":"심화 · 번역 단계와 코돈 계산","badge":"조용민T · 심화","question":"mRNA 5′-AUG GCU UAA GGG-3′를 첫 AUG에서 번역한다. 만들어지는 아미노산 수는?","passage":null,"answer":"2개","wrong":["1개","3개","4개"],"criteria":[],"explanation":"UAA에서 번역이 끝나므로 AUG와 GCU만 번역한다. 종결 뒤 GGG를 같은 폴리펩타이드에 계속 더하지 않는다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":47},{"id":"biology-jo-depth-011","deck_id":"biology-jo","kind":"choice","topic":"심화 · 번역 단계와 코돈 계산","badge":"조용민T · 심화","question":"mRNA 코돈 5′-GCU-3′에 역평행 결합하는 안티코돈을 5′→3′로 쓰면?","passage":null,"answer":"5′-AGC-3′","wrong":["5′-GCU-3′","5′-GCA-3′","5′-CGA-3′"],"criteria":[],"explanation":"상보 안티코돈은 3′-CGA-5′다. 이를 5′→3′로 뒤집으면 AGC다. 염기 상보성만 적용하고 방향을 놓치지 않는다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":48},{"id":"biology-jo-depth-012","deck_id":"biology-jo","kind":"choice","topic":"심화 · 번역 단계와 코돈 계산","badge":"조용민T · 심화","question":"번역 신장 중 새 아미노아실-tRNA가 들어가는 리보솜 자리는?","passage":null,"answer":"A 자리","wrong":["P 자리","E 자리","프로모터"],"criteria":[],"explanation":"일반적인 신장에서는 새 tRNA가 A 자리로 들어간다. P는 펩타이딜-tRNA, E는 아미노산이 없는 tRNA의 방출과 관련된다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":49},{"id":"biology-jo-depth-013","deck_id":"biology-jo","kind":"choice","topic":"심화 · 번역 단계와 코돈 계산","badge":"조용민T · 심화","question":"번역 개시 직후 시작 아미노산을 운반한 tRNA가 위치하는 자리는?","passage":null,"answer":"P 자리","wrong":["A 자리","E 자리","핵공"],"criteria":[],"explanation":"개시 tRNA는 P 자리에 배치된다. 일반적인 신장 tRNA가 A 자리로 들어가는 것과 개시를 구별한다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":50},{"id":"biology-jo-depth-014","deck_id":"biology-jo","kind":"choice","topic":"심화 · 번역 단계와 코돈 계산","badge":"조용민T · 심화","question":"종결 코돈을 읽은 리보솜에서 직접 작용하는 것은?","passage":null,"answer":"방출 인자","wrong":["스플라이싱 효소","종결 아미노산 운반 tRNA","DNA 중합효소"],"criteria":[],"explanation":"종결 코돈에 대응하는 일반 아미노아실-tRNA 대신 방출 인자가 작용해 폴리펩타이드가 방출된다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":51},{"id":"biology-jo-depth-015","deck_id":"biology-jo","kind":"choice","topic":"심화 · 번역 단계와 코돈 계산","badge":"조용민T · 심화","question":"하나의 mRNA를 같은 방향으로 여러 리보솜이 번역한다. 더 아래쪽 리보솜의 폴리펩타이드는?","passage":null,"answer":"더 길 수 있다","wrong":["반드시 다른 단백질 서열이다","종결 코돈을 아미노산으로 포함","항상 더 짧다"],"criteria":[],"explanation":"같은 시작점과 읽는 틀에서 더 진행한 리보솜은 더 긴 사슬을 합성했을 수 있다. 위치 차이가 다른 유전자 번역을 뜻하지 않는다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":52},{"id":"biology-jo-depth-016","deck_id":"biology-jo","kind":"choice","topic":"심화 · 번역 단계와 코돈 계산","badge":"조용민T · 심화","question":"100개 아미노산의 단일 사슬을 지정하는 구간은 시작 코돈을 포함한다. 종결 코돈까지 필요한 최소 염기 수는?","passage":null,"answer":"303개","wrong":["300개","297개","101개"],"criteria":[],"explanation":"아미노산 코돈 100개에 종결 코돈 1개를 더하면 101×3=303개다. 시작 코돈은 이미 100개에 포함되어 두 번 세지 않는다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":53},{"id":"biology-jo-depth-017","deck_id":"biology-jo","kind":"choice","topic":"심화 · 번역 단계와 코돈 계산","badge":"조용민T · 심화","question":"아미노산 80개로 된 선형 폴리펩타이드의 펩타이드 결합 수는?","passage":null,"answer":"79개","wrong":["80개","81개","240개"],"criteria":[],"explanation":"선형 사슬의 연결 수는 구성 단위 수보다 하나 적다. 따라서 80−1=79개다. 코돈이나 염기 수와 혼동하지 않는다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":54},{"id":"biology-jo-depth-018","deck_id":"biology-jo","kind":"choice","topic":"심화 · 번역 단계와 코돈 계산","badge":"조용민T · 심화","question":"mRNA AUG-AAA-UAG의 UAG가 UGG로 바뀌었다. 다른 조건이 같고 뒤쪽에 코돈이 더 있다면?","passage":null,"answer":"뒤의 종결 코돈까지 더 길어질 수 있다","wrong":["DNA 염색체 수가 증가한다","항상 아미노산 수가 한 개 준다","번역 시작이 반드시 사라진다"],"criteria":[],"explanation":"종결 코돈이 아미노산 코돈으로 바뀌면 기존 위치에서 끝나지 않아 다음 종결까지 합성될 수 있다. 길이 변화는 뒤쪽 서열에 달려 있다.","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":55},{"id":"biology-jo-depth-written-001","deck_id":"biology-jo","kind":"written","topic":"심화 · 가닥 방향·전사·RNA 가공","badge":null,"question":"DNA 주형이 3′-TAC GGA ATT-5′일 때 mRNA와 암호화 DNA를 쓰고 두 가닥의 관계를 설명하시오.","passage":null,"answer":"mRNA는 5′-AUG CCU UAA-3′이고 암호화 DNA는 5′-ATG CCT TAA-3′다. 주형과 RNA는 상보적이며 역평행이다. 같은 5′→3′ 방향에서 암호화 DNA와 RNA는 T와 U 차이를 제외하면 같은 서열이다.","wrong":[],"criteria":["mRNA 서열·방향","암호화 DNA 서열·방향","상보·역평행 및 T/U 구별"],"explanation":"","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":1010},{"id":"biology-jo-depth-written-002","deck_id":"biology-jo","kind":"written","topic":"심화 · 번역 단계와 코돈 계산","badge":null,"question":"5′-AUG GCU UUU UGA-3′를 첫 AUG에서 번역할 때 아미노산 수와 결합 수를 구하고, GCU의 안티코돈을 5′→3′로 쓰시오.","passage":null,"answer":"종결 UGA는 아미노산을 지정하지 않으므로 아미노산은 3개, 펩타이드 결합은 2개다. GCU의 상보 안티코돈은 3′-CGA-5′이므로 5′→3′로 쓰면 5′-AGC-3′다. 코돈과 안티코돈은 상보적이고 역평행이다.","wrong":[],"criteria":["아미노산 3·결합 2","안티코돈 AGC와 방향","종결·역평행 설명"],"explanation":"","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":1011},{"id":"biology-jo-depth-written-003","deck_id":"biology-jo","kind":"written","topic":"심화 · 번역 단계와 코돈 계산","badge":null,"question":"리보솜의 A·P·E 자리와 번역 개시·신장·종결을 연결해 설명하시오.","passage":null,"answer":"개시 tRNA는 P 자리에 놓이며 신장 때 새 아미노아실-tRNA는 A 자리로 들어간다. 펩타이드가 A 자리 tRNA로 옮겨지고 전위하면서 사슬을 가진 tRNA가 P로 이동한다. 아미노산이 없는 tRNA는 E를 거쳐 빠져나가고 종결 코돈에서는 방출 인자가 작용한다.","wrong":[],"criteria":["개시 P·신장 A","전위와 E 방출","종결의 방출 인자"],"explanation":"","source_label":"조용민T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":1012},{"id":"biology-park-depth-001","deck_id":"biology-park","kind":"choice","topic":"심화 · HGP·SNP·GWAS","badge":"박상영T · 심화","question":"환자와 대조군의 수많은 SNP 빈도를 비교해 질병과 연관된 위치를 찾았다. 이에 해당하는 연구는?","passage":null,"answer":"GWAS","wrong":["한 개체의 핵형 분석","단백질 분해 실험","유전자 발현량만 측정"],"criteria":[],"explanation":"GWAS는 집단에서 유전체 전반의 유전 변이와 형질 간 연관을 조사한다. 핵형 분석은 염색체 수와 구조를 확인한다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":69},{"id":"biology-park-depth-002","deck_id":"biology-park","kind":"choice","topic":"심화 · HGP·SNP·GWAS","badge":"박상영T · 심화","question":"HGP와 GWAS를 비교한 설명 중 옳은 것은?","passage":null,"answer":"HGP는 서열, GWAS는 형질 연관 조사","wrong":["GWAS는 모든 SNP의 인과성을 증명","HGP는 질병 확진, GWAS는 염색체 계수","HGP와 GWAS는 모두 한 가계만 조사"],"criteria":[],"explanation":"HGP는 인간 유전체의 지도와 서열을 구축한 프로젝트다. GWAS의 통계적 연관 결과만으로 원인 변이를 확정할 수 없다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":70},{"id":"biology-park-depth-003","deck_id":"biology-park","kind":"choice","topic":"심화 · HGP·SNP·GWAS","badge":"박상영T · 심화","question":"두 사람의 같은 DNA 위치가 각각 A와 G다. 이 차이가 집단에서 관찰되는 한 염기 다형성이면?","passage":null,"answer":"SNP","wrong":["염색체 비분리","전좌","염색체 역위"],"criteria":[],"explanation":"한 염기 위치에서 관찰되는 다형성은 SNP다. 큰 염색체 구간의 방향이나 개수 변화와 구별한다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":71},{"id":"biology-park-depth-004","deck_id":"biology-park","kind":"choice","topic":"심화 · HGP·SNP·GWAS","badge":"박상영T · 심화","question":"GWAS에서 p=10⁻⁹인 SNP A와 p=10⁻⁶인 SNP B의 맨해튼 플롯 높이를 비교하면?","passage":null,"answer":"A가 3 높다","wrong":["B가 3 높다","A와 B의 높이가 같다","A가 B의 1000배 높다"],"criteria":[],"explanation":"세로축 −log₁₀(p)는 A에서 9, B에서 6이다. 따라서 높이 차는 3이며 p의 비와 높이의 비를 혼동하지 않는다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":72},{"id":"biology-park-depth-005","deck_id":"biology-park","kind":"choice","topic":"심화 · HGP·SNP·GWAS","badge":"박상영T · 심화","question":"한 GWAS의 기준이 p<5×10⁻⁸이다. 유의한 결과에 해당하는 것은?","passage":null,"answer":"p=2×10⁻⁹","wrong":["p=8×10⁻⁸","p=10⁻⁶","p=0.01"],"criteria":[],"explanation":"2×10⁻⁹만 주어진 기준보다 작다. 유의성 기준은 문제의 조건을 따르며 p가 작다고 효과 크기가 큰 것은 아니다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":73},{"id":"biology-park-depth-006","deck_id":"biology-park","kind":"choice","topic":"심화 · HGP·SNP·GWAS","badge":"박상영T · 심화","question":"맨해튼 플롯의 한 봉우리가 매우 높다. 이 결과만으로 확정할 수 없는 것은?","passage":null,"answer":"해당 SNP가 직접 질병을 일으킨다","wrong":["기준 초과 여부를 확인할 수 있다","해당 SNP의 p값이 작다","그 위치에 연관 신호가 있다"],"criteria":[],"explanation":"연관된 SNP가 원인 변이 근처의 표지자일 수 있다. 인과성은 후속 기능 연구와 독립 검증이 필요하다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":74},{"id":"biology-park-depth-007","deck_id":"biology-park","kind":"choice","topic":"심화 · HGP·SNP·GWAS","badge":"박상영T · 심화","question":"GWAS에서 같은 SNP의 p가 더 작게 나왔다. 이에 대한 옳은 해석은?","passage":null,"answer":"연관의 통계적 근거가 더 강하다","wrong":["효과 크기가 반드시 더 크다","모든 보유자가 질병에 걸린다","질병 발생 확률이 p와 같다"],"criteria":[],"explanation":"p값은 귀무가설 아래의 통계적 근거와 관련된다. 개인의 발병 확률이나 효과 크기를 직접 나타내지 않는다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":75},{"id":"biology-park-depth-008","deck_id":"biology-park","kind":"choice","topic":"심화 · HGP·SNP·GWAS","badge":"박상영T · 심화","question":"서로 다른 집단을 섞은 GWAS에서 SNP와 질병이 연관됐다. 집단 구성 차이를 점검하는 이유는?","passage":null,"answer":"집단 차이가 가짜 연관을 만들 수 있다","wrong":["집단을 섞으면 SNP가 사라진다","혼합 집단에는 염색체가 없다","p값은 항상 정확히 0이 된다"],"criteria":[],"explanation":"집단별 대립유전자 빈도와 질병 빈도가 다르면 혼합 자체가 연관처럼 보일 수 있다. 독립 재현과 집단 구조 점검이 필요하다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":76},{"id":"biology-park-depth-009","deck_id":"biology-park","kind":"choice","topic":"심화 · HGP·SNP·GWAS","badge":"박상영T · 심화","question":"같은 SNP 위치에서 환자 100명 중 A 대립유전자 보유자는 60명, 대조군 100명 중에는 30명이다. 타당한 결론은?","passage":null,"answer":"표본에서 A 보유와 질병이 연관된다","wrong":["A가 질병의 유일한 원인이다","A를 가진 사람은 모두 환자다","A가 없으면 질병에 걸리지 않는다"],"criteria":[],"explanation":"표본의 보유율 차이는 연관의 단서다. 이 수치만으로 원인·충분조건·필요조건을 확정할 수 없다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":77},{"id":"biology-park-depth-010","deck_id":"biology-park","kind":"choice","topic":"심화 · HGP·SNP·GWAS","badge":"박상영T · 심화","question":"한 사람의 SNP A 보유 여부만으로 다인자 질환을 확진할 수 없다는 설명의 근거는?","passage":null,"answer":"다른 유전 요인과 환경도 관여한다","wrong":["SNP는 언제나 단백질을 제거한다","모든 SNP는 염색체 밖에 있다","다인자 질환에는 유전 요인이 없다"],"criteria":[],"explanation":"다인자 형질에는 여러 유전 요인과 환경이 함께 영향을 준다. 연관 SNP 한 개는 확진 도구와 같지 않다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":78},{"id":"biology-park-depth-011","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"감수 1분열 전기의 교차가 일반적으로 일어나는 두 구조는?","passage":null,"answer":"상동염색체의 비자매염색분체","wrong":["서로 다른 세포의 염색체","mRNA와 tRNA","같은 염색체의 두 자매염색분체"],"criteria":[],"explanation":"상동염색체가 접합한 뒤 비자매염색분체 사이에서 DNA 구간을 교환한다. 자매염색분체의 단순 복제와 구별한다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":79},{"id":"biology-park-depth-012","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"키아즈마를 교차와 연결한 설명 중 옳은 것은?","passage":null,"answer":"교차 결과 상동염색체가 연결된 부위","wrong":["DNA 복제가 시작되는 모든 위치","자매염색분체의 동원체만 지칭","비상동염색체 구간 교환 부위"],"criteria":[],"explanation":"키아즈마는 교차의 결과로 관찰되는 상동염색체의 연결 부위이며 감수 1분열의 적절한 분리에 기여한다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":80},{"id":"biology-park-depth-013","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"교차가 유전적 다양성을 높이는 주된 까닭은?","passage":null,"answer":"기존 대립유전자의 조합을 바꾼다","wrong":["염색체 수를 반드시 두 배로 늘린다","모든 유전자의 염기서열을 새로 만든다","각 생식세포의 DNA를 없앤다"],"criteria":[],"explanation":"정상적인 교차는 대응하는 DNA 구간을 교환해 새로운 대립유전자 조합을 만든다. 새 대립유전자 생성과 구별한다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":81},{"id":"biology-park-depth-014","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"AB/ab인 상동염색체의 네 염색분체 중 두 비자매염색분체만 A와 B 사이에서 한 번 교차했다. 생성 가능한 네 산물은?","passage":null,"answer":"AB·ab·Ab·aB","wrong":["AA·BB·aa·bb","AB·AB·ab·ab","Ab·Ab·aB·aB"],"criteria":[],"explanation":"교차에 참여하지 않은 두 염색분체는 AB와 ab다. 참여한 두 염색분체는 Ab와 aB가 되어 한 감수분열에서 재조합형이 둘 나온다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":82},{"id":"biology-park-depth-015","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"AB/ab 개체를 ab/ab와 검정교배했다. AB:420, ab:380, Ab:100, aB:100이면 재조합률은?","passage":null,"answer":"20%","wrong":["40%","80%","10%"],"criteria":[],"explanation":"재조합형은 Ab와 aB로 200개이며 전체 1000개다. 200/1000×100=20%다. 한 재조합형만 세지 않는다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":83},{"id":"biology-park-depth-016","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"Ab/aB 개체를 ab/ab와 검정교배했다. 가장 많은 두 자손형이 Ab와 aB라면 부모형은?","passage":null,"answer":"Ab와 aB","wrong":["AB와 ab","AB와 aB","Ab와 ab"],"criteria":[],"explanation":"부모형은 이형접합 부모가 가진 대립유전자 조합이다. 같은 AaBb라도 연관 배열에 따라 부모형이 달라진다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":84},{"id":"biology-park-depth-017","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"AB/ab 개체의 재조합률이 12%다. 생식세포 비율이 대칭이면 Ab 생식세포의 비율은?","passage":null,"answer":"6%","wrong":["12%","44%","88%"],"criteria":[],"explanation":"재조합형 Ab와 aB가 합쳐 12%이므로 각 6%다. 부모형 AB와 ab는 각각 44%다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":85},{"id":"biology-park-depth-018","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"AB/ab 개체가 교차 없이 감수분열하고 두 유전자는 완전 연관되어 있다. 가능한 생식세포는?","passage":null,"answer":"AB와 ab","wrong":["AA와 bb","AB·Ab·aB·ab","Ab와 aB"],"criteria":[],"explanation":"동일 염색체에 있는 두 유전자의 조합은 교차가 없으면 유지된다. 서로 다른 염색체에 있는 독립 분리와 구별한다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":86},{"id":"biology-park-depth-019","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"서로 다른 염색체의 A/a와 B/b가 독립적으로 분리된다. 가능한 생식세포 조합 수는?","passage":null,"answer":"4","wrong":["8","16","2"],"criteria":[],"explanation":"두 상동염색체 쌍의 독립적 분리로 AB, Ab, aB, ab가 가능하다. 이 다양성은 두 좌위 사이 교차 없이도 생긴다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":87},{"id":"biology-park-depth-020","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"교차와 돌연변이의 차이를 옳게 설명한 것은?","passage":null,"answer":"교차는 조합, 돌연변이는 변이를 바꾼다","wrong":["교차는 반드시 염색체 수를 바꾼다","돌연변이는 기존 조합만 섞는다","두 과정은 모두 번역에서만 일어난다"],"criteria":[],"explanation":"정상적인 교차는 기존 변이의 조합을 바꾸며 돌연변이는 서열이나 염색체에 새로운 변화를 만든다. 불균등 교차 같은 예외는 구별한다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":88},{"id":"biology-park-depth-021","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"한 감수분열에서 상동염색체 쌍의 두 비자매염색분체가 한 번 교차했다. 재조합형 염색분체 수는?","passage":null,"answer":"2개","wrong":["1개","3개","4개"],"criteria":[],"explanation":"4개의 염색분체 중 교차에 참여한 2개만 해당 구간에서 재조합형이 된다. 개체군 전체 재조합률과 한 세포의 산물을 구별한다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":89},{"id":"biology-park-depth-022","deck_id":"biology-park","kind":"choice","topic":"심화 · 키아즈마·교차·연관","badge":"박상영T · 심화","question":"두 유전자 사이 다중 교차를 고려하지 않고 재조합형 비율만 지도 거리로 삼았다. 생길 수 있는 문제는?","passage":null,"answer":"실제 교차 거리를 과소 추정한다","wrong":["교차가 돌연변이로 바뀐다","재조합률이 항상 100%가 된다","부모형이 모두 소멸한다"],"criteria":[],"explanation":"이중 교차 중 일부는 양 끝 표지자의 부모형 조합을 회복시킨다. 따라서 관찰 재조합형만 세면 교차 사건을 놓칠 수 있다.","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":90},{"id":"biology-park-depth-023","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"멘델 연구의 1865년과 1866년을 올바르게 구별한 것은?","passage":null,"answer":"1865 발표·1866 논문 출판","wrong":["1865 재발견·1866 최초 발표","1865 염색체설·1866 성연관 발견","1865 DNA 발견·1866 복제 증명"],"criteria":[],"explanation":"멘델은 1865년 연구를 발표하고 1866년 논문을 출판했다. 발표와 출판을 같은 사건으로 뭉뚱그리지 않는다.","source_label":"박상영T 필기 · 연혁 공식 자료 대조","source_page":1,"source_slide":null,"source_url":null,"sort":91},{"id":"biology-park-depth-024","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"1900년에 멘델 연구를 재발견한 인물 묶음은?","passage":null,"answer":"드브리스·코렌스·체르마크","wrong":["서턴·보베리·모건","그리피스·에이버리·체이스","왓슨·크릭·프랭클린"],"criteria":[],"explanation":"1900년 멘델 연구의 재발견은 드브리스, 코렌스, 체르마크와 연결된다. 다른 묶음은 염색체·DNA 연구와 관련된다.","source_label":"박상영T 필기 · 연혁 공식 자료 대조","source_page":1,"source_slide":null,"source_url":null,"sort":92},{"id":"biology-park-depth-025","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"감수분열 때 상동염색체 분리와 멘델의 분리 법칙을 연결한 연구는?","passage":null,"answer":"서턴·보베리의 염색체설","wrong":["그리피스의 형질전환","허시·체이스의 동위원소 실험","왓슨·크릭의 이중 나선 모형"],"criteria":[],"explanation":"1902~1903년 염색체설은 유전인자의 전달과 감수분열의 염색체 행동을 연결한다. DNA의 화학적 정체를 밝힌 실험과 다르다.","source_label":"박상영T 필기 · 연혁 공식 자료 대조","source_page":1,"source_slide":null,"source_url":null,"sort":93},{"id":"biology-park-depth-026","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"모건의 흰눈 초파리 성연관 유전 결과가 발표된 연도는?","passage":null,"answer":"1910년","wrong":["1952년","1900년","1928년"],"criteria":[],"explanation":"흰눈 초파리 성연관 결과는 1910년에 발표됐다. 필기의 1905 표기는 이 사건의 발표 연도와 구별해 기억한다.","source_label":"박상영T 필기 · 연혁 공식 자료 대조","source_page":1,"source_slide":null,"source_url":null,"sort":94},{"id":"biology-park-depth-027","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"그리피스 1928 → 에이버리 연구진 1944의 순서를 설명한 것은?","passage":null,"answer":"현상 발견 → 물질의 정체 확인","wrong":["동위원소 추적 → 형질전환 발견","DNA 복제 → 멘델 법칙 재발견","이중 나선 → 염색체설"],"criteria":[],"explanation":"그리피스는 형질전환을 관찰했고 에이버리 연구진은 효소 처리 등으로 형질전환 물질이 DNA라는 근거를 얻었다.","source_label":"박상영T 필기","source_page":3,"source_slide":null,"source_url":null,"sort":95},{"id":"biology-park-depth-028","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"살아 있는 R형과 가열 사멸 S형을 섞어 주입한 생쥐에서 살아 있는 S형이 검출됐다. 그리피스의 결론은?","passage":null,"answer":"R형이 형질전환되었다","wrong":["사멸 S형이 단순히 되살아났다","단백질이 유전물질임을 확정했다","RNA가 유전물질임을 확정했다"],"criteria":[],"explanation":"죽은 S형에서 유래한 물질이 살아 있는 R형의 유전적 성질을 바꿨다. 이 실험만으로 그 물질을 DNA로 확정하지 않았다.","source_label":"박상영T 필기","source_page":3,"source_slide":null,"source_url":null,"sort":96},{"id":"biology-park-depth-029","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"S형 추출물에 단백질 분해효소나 RNase를 넣어도 형질전환되지만 DNase에서는 안 된다. 핵심 결론은?","passage":null,"answer":"DNA가 형질전환에 필요하다","wrong":["단백질이 형질전환의 유일 원인이다","효소 종류와 결과는 무관하다","RNA 분해가 DNA를 만들었다"],"criteria":[],"explanation":"단백질과 RNA를 분해해도 활성이 남지만 DNA를 분해하면 사라지므로 DNA가 형질전환에 필요한 물질이라는 근거다.","source_label":"박상영T 필기","source_page":3,"source_slide":null,"source_url":null,"sort":97},{"id":"biology-park-depth-030","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"에이버리 실험의 효소 처리군을 비교하려면 함께 필요한 대조 조건은?","passage":null,"answer":"동일 추출물의 효소 무처리군","wrong":["모든 처리군을 다른 온도로 배양","다른 세균의 염색체 수","생쥐의 털 색"],"criteria":[],"explanation":"효소 무처리군에서 형질전환이 가능함을 확인하고 다른 조건을 일정하게 해야 효소 처리 효과를 비교할 수 있다.","source_label":"박상영T 필기","source_page":3,"source_slide":null,"source_url":null,"sort":98},{"id":"biology-park-depth-031","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"허시·체이스 실험에서 DNA와 단백질의 표지에 각각 사용한 것은?","passage":null,"answer":"³²P와 ³⁵S","wrong":["둘 다 ³⁵S","둘 다 ³²P","³⁵S와 ³²P"],"criteria":[],"explanation":"DNA의 인산기에 인이 있고 일반적인 DNA에는 황이 없다. 단백질의 황 함유 아미노산은 ³⁵S로 추적한다.","source_label":"박상영T 필기","source_page":3,"source_slide":null,"source_url":null,"sort":99},{"id":"biology-park-depth-032","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"허시·체이스 실험에서 세균을 감염시킨 뒤 교반하는 주된 목적은?","passage":null,"answer":"세균 표면의 파지 껍질을 분리한다","wrong":["DNA를 아미노산으로 분해한다","세균을 모두 사멸시킨다","동위원소를 서로 바꾼다"],"criteria":[],"explanation":"교반으로 세균 표면에 남은 파지 단백질 껍질을 떼어낸 뒤 원심분리하여 세균과 껍질의 표지 분포를 비교한다.","source_label":"박상영T 필기","source_page":3,"source_slide":null,"source_url":null,"sort":100},{"id":"biology-park-depth-033","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"파지 감염·교반·원심분리 후 세균 침전에서 주로 검출된 표지는?","passage":null,"answer":"³²P","wrong":["³⁵S","두 표지가 항상 같은 비율","방사성 표지가 전혀 없음"],"criteria":[],"explanation":"DNA에 표지한 ³²P가 세균 침전에 주로 나타나며 단백질에 표지한 ³⁵S는 상층액에 주로 남는다. 결과는 절대 100%로 단정하지 않는다.","source_label":"박상영T 필기","source_page":3,"source_slide":null,"source_url":null,"sort":101},{"id":"biology-park-depth-034","deck_id":"biology-park","kind":"choice","topic":"심화 · 연구 연혁과 실험 증거","badge":"박상영T · 심화","question":"1953년 DNA 이중 나선 모형의 근거와 관련 인물 연결은?","passage":null,"answer":"프랭클린·윌킨스의 X선 연구","wrong":["서턴의 파지 동위원소 표지","그리피스의 mRNA 코돈표","멘델의 세균 원심분리"],"criteria":[],"explanation":"왓슨·크릭의 구조 모형에는 샤가프의 염기 조성 및 프랭클린·윌킨스의 X선 연구 등이 근거가 됐다. 구조 제안과 데이터 획득을 구별한다.","source_label":"박상영T 필기","source_page":3,"source_slide":null,"source_url":null,"sort":102},{"id":"biology-park-depth-035","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"한 염색체 쌍이 감수 1분열에서 비분리하고 2분열은 정상이다. 네 생식세포의 염색체 수는?","passage":null,"answer":"n+1 두 개·n−1 두 개","wrong":["정상 네 개","정상 세 개·n+1 한 개","정상 두 개·n+1·n−1"],"criteria":[],"explanation":"상동염색체가 한쪽으로 함께 이동하므로 1분열 후 두 세포 모두 해당 쌍의 수가 비정상이다. 2분열 후에도 정상 산물이 없다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":103},{"id":"biology-park-depth-036","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"감수 1분열은 정상이고 두 세포 중 하나만 한 염색체에서 2분열 비분리했다. 네 생식세포는?","passage":null,"answer":"정상 두 개·n+1·n−1","wrong":["n+1 두 개·n−1 두 개","정상 네 개","n+1 세 개·n−1 한 개"],"criteria":[],"explanation":"비분리하지 않은 세포에서 정상 생식세포 둘이 나온다. 비분리한 세포에서는 n+1과 n−1이 각각 하나 나온다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":104},{"id":"biology-park-depth-037","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"n−1 생식세포가 정상 n 생식세포와 수정했다. 접합자의 염색체 수는?","passage":null,"answer":"2n−1","wrong":["2n+1","n−1","2n"],"criteria":[],"explanation":"n−1+n=2n−1이다. 단염색체성은 정상 한 쌍 중 하나가 없는 상태이며 배수성 변화와 다르다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":105},{"id":"biology-park-depth-038","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"핵형 47,XX,+21의 대표적 수 이상은?","passage":null,"answer":"21번 삼염색체성","wrong":["X 염색체 역위","18번 삼염색체성","성염색체 단염색체성"],"criteria":[],"explanation":"47개의 염색체 중 21번이 추가된 핵형이다. 대표적인 다운 증후군의 수 이상과 연결되며 모든 사례가 이 핵형이라는 뜻은 아니다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":106},{"id":"biology-park-depth-039","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"총 47개 염색체이며 성염색체가 XXY인 핵형은?","passage":null,"answer":"클라인펠터 증후군","wrong":["고양이 울음 증후군","에드워드 증후군","터너 증후군"],"criteria":[],"explanation":"47,XXY는 클라인펠터 증후군의 대표 핵형이다. 터너는 대표적으로 45,X이며 18번 삼염색체성과 구별한다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":107},{"id":"biology-park-depth-040","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"핵형 45,X에서 부족한 염색체와 대표 증후군의 연결은?","passage":null,"answer":"성염색체 하나·터너","wrong":["21번 하나·다운","18번 하나·에드워드","Y 하나·클라인펠터"],"criteria":[],"explanation":"45,X는 성염색체가 하나인 대표적인 터너 증후군 핵형이다. Y가 사라진 남성이라고 단정하지 않는다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":108},{"id":"biology-park-depth-041","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"18번 염색체가 세 개 있는 대표적 수 이상은?","passage":null,"answer":"에드워드 증후군","wrong":["다운 증후군","터너 증후군","고양이 울음 증후군"],"criteria":[],"explanation":"에드워드 증후군은 대표적으로 18번 삼염색체성이다. 다운은 21번, 고양이 울음 증후군은 5번 짧은 팔 결실과 연결된다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":109},{"id":"biology-park-depth-042","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"염색체 배열 ABCDEFG가 ABCEFG로 바뀌었다. 변화는?","passage":null,"answer":"결실","wrong":["전좌","중복","역위"],"criteria":[],"explanation":"D 구간이 없어졌으므로 결실이다. 염색체 개수 자체가 정상이어도 구조 이상이 있을 수 있다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":110},{"id":"biology-park-depth-043","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"한 염색체 배열 ABCDEFG가 ABCDCDEFG로 바뀌었다. 변화는?","passage":null,"answer":"중복","wrong":["역위","단염색체성","결실"],"criteria":[],"explanation":"CD 구간이 한 번 더 존재하므로 중복이다. 유전자 양의 변화는 유전자 발현에 영향을 줄 수 있다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":111},{"id":"biology-park-depth-044","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"염색체 배열 ABCDEFG가 ABEDCFG로 바뀌었다. 변화는?","passage":null,"answer":"역위","wrong":["중복","삼염색체성","단염색체성"],"criteria":[],"explanation":"CDE 구간이 EDC로 반전됐으므로 역위다. 구간의 소실이나 복제 없이 배열 방향이 바뀔 수 있다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":112},{"id":"biology-park-depth-045","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"서로 비상동인 두 염색체가 구간을 교환했다. 상동염색체의 정상 교차와 구별되는 변화는?","passage":null,"answer":"상호 전좌","wrong":["독립적 분리","DNA 반보존적 복제","염기 치환"],"criteria":[],"explanation":"비상동염색체 사이의 구간 교환은 상호 전좌다. 대응 좌위가 있는 상동염색체의 정상 교차와 구별한다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":113},{"id":"biology-park-depth-046","deck_id":"biology-park","kind":"choice","topic":"심화 · 비분리와 염색체 이상","badge":"박상영T · 심화","question":"유전자 양 손실 없는 균형 전좌 보유자도 비정상 자손을 가질 수 있는 주된 이유는?","passage":null,"answer":"감수분열에서 불균형 산물이 가능하다","wrong":["정상 생식세포는 절대 만들지 못한다","체세포의 모든 염색체가 사라진다","전좌는 반드시 RNA를 제거한다"],"criteria":[],"explanation":"보유자의 양적 균형이 유지돼도 감수분열의 분리 방식에 따라 결실·중복이 있는 생식세포가 생길 수 있다. 정상 산물도 가능하다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":114},{"id":"biology-park-depth-047","deck_id":"biology-park","kind":"choice","topic":"심화 · 돌연변이 원인과 결과","badge":"박상영T · 심화","question":"DNA 복제 중 잘못 들어간 염기가 수선되지 않고 다음 복제에 전달됐다. 원인은?","passage":null,"answer":"자연발생 복제 오류","wrong":["정상적인 독립 분리","상동염색체의 정상 배열","항상 자외선 조사"],"criteria":[],"explanation":"외부 변이원 없이도 복제 오류가 교정되지 않으면 돌연변이로 고정될 수 있다. 모든 돌연변이를 방사선 탓으로 돌리지 않는다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":115},{"id":"biology-park-depth-048","deck_id":"biology-park","kind":"choice","topic":"심화 · 돌연변이 원인과 결과","badge":"박상영T · 심화","question":"돌연변이 유발 요인 묶음으로 옳은 것은?","passage":null,"answer":"자외선·방사선·일부 화학 물질","wrong":["독립 분리·정상 교차·수정","정상 복제·정상 수선·정상 분리","무작위 수정·정상 접합·정상 배열"],"criteria":[],"explanation":"자외선과 방사선, 일부 화학 물질은 DNA 손상을 유발할 수 있다. 정상적인 감수분열 조합 변화와 구별한다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":116},{"id":"biology-park-depth-049","deck_id":"biology-park","kind":"choice","topic":"심화 · 돌연변이 원인과 결과","badge":"박상영T · 심화","question":"성인의 피부 세포에서만 발생한 변이에 대한 설명은?","passage":null,"answer":"피부 세포 계통에 전달될 수 있다","wrong":["모든 자녀에게 반드시 전달된다","몸의 모든 세포가 즉시 변한다","다음 감수분열에서 항상 사라진다"],"criteria":[],"explanation":"체세포 변이는 해당 세포의 분열로 세포 계통에 전달될 수 있다. 생식세포 계통에 없으면 일반적인 유성생식으로 자손에게 전달되지 않는다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":117},{"id":"biology-park-depth-050","deck_id":"biology-park","kind":"choice","topic":"심화 · 돌연변이 원인과 결과","badge":"박상영T · 심화","question":"mRNA 코돈 GAA가 GAG로 바뀌었고 둘 다 글루탐산을 지정한다. 암호화 결과는?","passage":null,"answer":"침묵 돌연변이","wrong":["염색체 비분리","미스센스 돌연변이","넌센스 돌연변이"],"criteria":[],"explanation":"유전 암호의 중복성 때문에 염기가 달라도 아미노산이 같을 수 있다. 아미노산 서열이 유지되는 치환을 침묵 돌연변이라고 한다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":118},{"id":"biology-park-depth-051","deck_id":"biology-park","kind":"choice","topic":"심화 · 돌연변이 원인과 결과","badge":"박상영T · 심화","question":"mRNA GAG(글루탐산)가 GUG(발린)으로 바뀌었다. 결과는?","passage":null,"answer":"미스센스 돌연변이","wrong":["넌센스 돌연변이","항상 읽는 틀 이동","침묵 돌연변이"],"criteria":[],"explanation":"다른 아미노산을 지정하는 치환은 미스센스다. 낫 모양 적혈구의 대표적 β글로빈 변이처럼 단백질 성질에 영향을 줄 수 있다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":119},{"id":"biology-park-depth-052","deck_id":"biology-park","kind":"choice","topic":"심화 · 돌연변이 원인과 결과","badge":"박상영T · 심화","question":"아미노산을 지정하던 UAU가 종결 코돈 UAA로 바뀌었다. 결과는?","passage":null,"answer":"넌센스 돌연변이","wrong":["침묵 돌연변이","염색체 중복","상동염색체 전좌"],"criteria":[],"explanation":"아미노산 코돈이 종결 코돈으로 바뀌면 번역이 조기에 끝날 수 있다. 이는 넌센스 돌연변이이며 종결 코돈은 아미노산을 지정하지 않는다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":120},{"id":"biology-park-depth-053","deck_id":"biology-park","kind":"choice","topic":"심화 · 돌연변이 원인과 결과","badge":"박상영T · 심화","question":"암호화 구간 중간에 염기 1개가 삽입됐다. 이후 번역에서 예상되는 변화는?","passage":null,"answer":"읽는 틀이 이동할 수 있다","wrong":["읽는 틀이 반드시 유지된다","염색체 수가 한 개 증가한다","항상 같은 아미노산 하나만 추가된다"],"criteria":[],"explanation":"3의 배수가 아닌 삽입은 이후 코돈을 나누는 기준을 바꾼다. 영향은 삽입 위치와 종결 코돈 등에 따라 달라진다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":121},{"id":"biology-park-depth-054","deck_id":"biology-park","kind":"choice","topic":"심화 · 돌연변이 원인과 결과","badge":"박상영T · 심화","question":"암호화 구간에서 연속 3염기가 결실됐다. 1염기 결실과 비교한 옳은 설명은?","passage":null,"answer":"뒤쪽 읽는 틀은 유지될 수 있다","wrong":["뒤쪽 코돈은 반드시 전부 바뀐다","단백질 기능이 반드시 정상이다","염색체 하나가 반드시 소실된다"],"criteria":[],"explanation":"3염기 결실은 뒤쪽 읽는 틀을 유지할 수 있지만 단백질의 아미노산 및 기능은 달라질 수 있다. 틀 유지와 기능 정상을 구별한다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":122},{"id":"biology-park-depth-055","deck_id":"biology-park","kind":"choice","topic":"심화 · 돌연변이 원인과 결과","badge":"박상영T · 심화","question":"생식세포 DNA에 생긴 변이가 자손에게 전달될 수 있는 조건은?","passage":null,"answer":"그 생식세포가 수정에 참여한다","wrong":["모든 체세포가 같은 변이를 가진다","그 변이가 반드시 우성이다","피부에만 변이가 있다"],"criteria":[],"explanation":"생식세포 계통의 변이는 수정에 참여하면 자손에게 전달될 수 있다. 우성 여부는 전달 자체와 다른 문제다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":123},{"id":"biology-park-depth-056","deck_id":"biology-park","kind":"choice","topic":"심화 · 돌연변이 원인과 결과","badge":"박상영T · 심화","question":"DNA 수선 기능이 약해진 세포에서 돌연변이가 늘 수 있는 까닭은?","passage":null,"answer":"손상·복제 오류가 더 남기 쉽다","wrong":["유전 암호의 코돈 수가 줄어든다","모든 상동염색체가 독립 분리된다","정상 교차가 전부 중단된다"],"criteria":[],"explanation":"DNA 손상과 복제 오류를 수선하지 못하면 변이가 고정될 가능성이 커진다. 수선 실패와 정상 감수분열 과정은 구별한다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":124},{"id":"biology-park-depth-057","deck_id":"biology-park","kind":"choice","topic":"심화 · 사람의 유전 자료 해석","badge":"박상영T · 심화","question":"ABO에서 집단에는 Iᴬ·Iᴮ·i가 있다. 정상 이배체 개인이 같은 좌위에서 가지는 대립유전자 수는?","passage":null,"answer":"2개","wrong":["3개","1개","혈액형에 따라 4개"],"criteria":[],"explanation":"복대립유전은 집단에 세 종류 이상이 있다는 뜻이다. 정상 이배체 개인은 상동염색체에서 하나씩 두 개를 가진다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":125},{"id":"biology-park-depth-058","deck_id":"biology-park","kind":"choice","topic":"심화 · 사람의 유전 자료 해석","badge":"박상영T · 심화","question":"Iᴬi와 Iᴮi인 부모의 자녀가 AB형일 확률은?","passage":null,"answer":"1/4","wrong":["0","1/2","3/4"],"criteria":[],"explanation":"가능 유전형은 IᴬIᴮ, Iᴬi, Iᴮi, ii가 각각 1/4다. AB형은 IᴬIᴮ 한 경우다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":126},{"id":"biology-park-depth-059","deck_id":"biology-park","kind":"choice","topic":"심화 · 사람의 유전 자료 해석","badge":"박상영T · 심화","question":"ABO 유전형 IᴬIᴮ, H 좌위 hh인 사람의 봄베이 표현형을 설명한 것은?","passage":null,"answer":"H 항원이 없어 A·B 항원 형성 제한","wrong":["B 항원만 정상적으로 형성","반드시 일반 AB형으로 표현","A 항원만 정상적으로 형성"],"criteria":[],"explanation":"hh에서는 A·B 항원을 만드는 바탕인 H 항원이 형성되지 않아 ABO 유전형과 항원 표현형이 다를 수 있다. 일반 O형과도 구별한다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":127},{"id":"biology-park-depth-060","deck_id":"biology-park","kind":"choice","topic":"심화 · 사람의 유전 자료 해석","badge":"박상영T · 심화","question":"ABO 유전형 IᴬIᴮ이고 H 좌위가 Hh다. 항원 형성에 대한 설명은?","passage":null,"answer":"H가 기능하면 A·B 항원 모두 가능","wrong":["h가 한쪽 B 항원만 막는다","H는 A만 만들고 h는 B만 만든다","Hh는 항상 봄베이 표현형이다"],"criteria":[],"explanation":"H/h는 ABO 대립유전자 각각에 붙어 한쪽만 켜고 끄는 스위치가 아니다. 우성 H가 H 항원 형성을 가능하게 하면 A·B 항원 모두 형성될 수 있다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":128},{"id":"biology-park-depth-061","deck_id":"biology-park","kind":"choice","topic":"심화 · 사람의 유전 자료 해석","badge":"박상영T · 심화","question":"어떤 형질 일치율이 일란성 54%, 이란성 12%다. 자료에 부합하는 해석은?","passage":null,"answer":"유전 영향이 시사되며 환경도 고려","wrong":["전적으로 유전만 결정한다","전적으로 환경만 결정한다","유전 기여도가 정확히 42%다"],"criteria":[],"explanation":"일란성에서 더 높은 일치율은 유전 영향의 단서이며 100% 미만이라는 점과 환경 차이 등을 함께 고려해야 한다. 단순 차이를 기여도로 삼지 않는다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":129},{"id":"biology-park-depth-062","deck_id":"biology-park","kind":"choice","topic":"심화 · 사람의 유전 자료 해석","badge":"박상영T · 심화","question":"상염색체 열성 형질에서 정상 부모 Aa×Aa의 정상 자녀 중 Aa일 조건부 확률은?","passage":null,"answer":"2/3","wrong":["3/4","1/2","1/4"],"criteria":[],"explanation":"자손 비율 AA:Aa:aa=1:2:1이다. 정상인 AA와 Aa만 남기면 3 중 2가 Aa이므로 조건부 확률은 2/3다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":130},{"id":"biology-park-depth-063","deck_id":"biology-park","kind":"choice","topic":"심화 · 사람의 유전 자료 해석","badge":"박상영T · 심화","question":"X 연관 열성에서 보인자 어머니 XᴬXᵃ와 정상 아버지 XᴬY의 아들 중 환자 비율은?","passage":null,"answer":"1/2","wrong":["0","1","1/4"],"criteria":[],"explanation":"아들은 아버지에게 Y, 어머니에게 X를 받는다. 어머니의 Xᵃ를 받을 확률이 1/2이므로 아들 중 환자가 1/2다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":131},{"id":"biology-park-depth-064","deck_id":"biology-park","kind":"choice","topic":"심화 · 사람의 유전 자료 해석","badge":"박상영T · 심화","question":"X 연관 열성에서 환자 아버지 XᵃY와 비보인자 어머니 XᴬXᴬ의 딸 유전형은?","passage":null,"answer":"모두 XᴬXᵃ","wrong":["모두 XᵃXᵃ","모두 XᴬXᴬ","절반 XᵃY"],"criteria":[],"explanation":"딸은 아버지의 Xᵃ와 어머니의 Xᴬ를 받는다. 모두 보인자이며 아버지의 X가 아들에게 직접 전달되지는 않는다.","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":132},{"id":"biology-park-depth-written-001","deck_id":"biology-park","kind":"written","topic":"심화 · HGP·SNP·GWAS","badge":null,"question":"HGP·SNP·GWAS를 구별하고, 유의한 SNP를 발견해도 원인 유전자를 확정할 수 없는 이유를 설명하시오.","passage":null,"answer":"HGP는 인간 유전체 지도와 염기서열을 구축한 프로젝트다. SNP는 한 염기 위치의 다형성이며 GWAS는 여러 SNP와 형질의 연관을 집단에서 조사한다. 유의한 SNP는 원인 변이와 가까운 표지자일 수 있으므로 연관만으로 인과성을 확정할 수 없다.","wrong":[],"criteria":["세 용어 구별","집단 수준의 연관 조사","표지자와 원인 변이 구별"],"explanation":"","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":1036},{"id":"biology-park-depth-written-002","deck_id":"biology-park","kind":"written","topic":"심화 · HGP·SNP·GWAS","badge":null,"question":"맨해튼 플롯에서 SNP A의 p=10⁻⁸, B의 p=10⁻⁵다. 두 높이를 계산하고, 높은 봉우리와 큰 유전적 효과가 같은 뜻인지 설명하시오.","passage":null,"answer":"−log₁₀(p)에 따라 A의 높이는 8, B의 높이는 5로 A가 3 높다. 높이는 연관의 통계적 유의성을 나타내며 효과 크기를 나타내지 않는다. 따라서 A의 유전적 효과가 B보다 반드시 크다고 결론 내릴 수 없다.","wrong":[],"criteria":["높이 8과 5","높이 차 3","유의성과 효과 크기 구별"],"explanation":"","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":1037},{"id":"biology-park-depth-written-003","deck_id":"biology-park","kind":"written","topic":"심화 · 키아즈마·교차·연관","badge":null,"question":"키아즈마가 유전적 다양성과 상동염색체 분리에 어떻게 연결되는지, 새 대립유전자 생성과 구별하여 설명하시오.","passage":null,"answer":"감수 1분열 전기에 상동염색체의 비자매염색분체가 대응 구간을 교환하면 기존 대립유전자의 조합이 바뀐다. 키아즈마는 이 교차의 결과로 나타나는 연결 부위이며 자매염색분체의 결합과 함께 상동염색체의 적절한 배열과 분리에 기여한다. 정상 교차의 조합 변화는 돌연변이에 의한 새 대립유전자 생성과 다르다.","wrong":[],"criteria":["비자매염색분체 교차","조합 변화와 새 변이 구별","키아즈마의 연결과 분리 기여"],"explanation":"","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":1038},{"id":"biology-park-depth-written-004","deck_id":"biology-park","kind":"written","topic":"심화 · 키아즈마·교차·연관","badge":null,"question":"AB/ab×ab/ab의 자손이 AB 360, ab 340, Ab 150, aB 150이다. 부모형·재조합형과 재조합률을 구하고, 두 재조합형을 모두 세야 하는 이유를 설명하시오.","passage":null,"answer":"부모형은 AB와 ab이고 재조합형은 Ab와 aB다. 재조합형 300개를 전체 1000개로 나누면 재조합률은 30%다. 교차에서 두 대응 구간을 교환하므로 서로 다른 두 재조합형이 모두 만들어져 두 종류를 합해야 한다.","wrong":[],"criteria":["부모형과 재조합형 구별","30% 계산","두 재조합형을 합산"],"explanation":"","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":1039},{"id":"biology-park-depth-written-005","deck_id":"biology-park","kind":"written","topic":"심화 · 키아즈마·교차·연관","badge":null,"question":"AB/ab의 한 감수분열에서 두 비자매염색분체가 한 번 교차한 경우의 네 산물을 쓰고, 이를 근거로 모든 생식세포가 반드시 재조합형이라는 주장을 반박하시오.","passage":null,"answer":"네 산물은 AB, ab, Ab, aB다. 교차에 참여하지 않은 두 염색분체는 부모형을 유지하고 참여한 두 염색분체만 재조합형이 된다. 따라서 한 번 교차했더라도 네 생식세포 중 둘은 부모형이며 모든 생식세포가 재조합형인 것은 아니다.","wrong":[],"criteria":["네 산물 제시","교차에 참여한 두 염색분체","부모형 두 개 유지"],"explanation":"","source_label":"박상영T 필기","source_page":1,"source_slide":null,"source_url":null,"sort":1040},{"id":"biology-park-depth-written-006","deck_id":"biology-park","kind":"written","topic":"심화 · 연구 연혁과 실험 증거","badge":null,"question":"그리피스와 에이버리 연구진의 연구를 연도·처리 방법·결론의 범위로 비교하시오.","passage":null,"answer":"1928년 그리피스는 살아 있는 R형과 사멸 S형의 혼합에서 형질전환을 관찰했지만 물질의 정체를 확정하지 못했다. 1944년 에이버리 연구진은 S형 추출물에 효소를 처리해 DNase에서만 활성이 사라지는 결과 등을 얻어 DNA가 형질전환 물질이라는 근거를 제시했다.","wrong":[],"criteria":["1928·1944 구별","혼합 실험과 효소 처리 구별","현상과 DNA 정체 구별"],"explanation":"","source_label":"박상영T 필기","source_page":3,"source_slide":null,"source_url":null,"sort":1041},{"id":"biology-park-depth-written-007","deck_id":"biology-park","kind":"written","topic":"심화 · 연구 연혁과 실험 증거","badge":null,"question":"허시·체이스 실험의 표지·교반·원심분리 결과를 연결하여 DNA가 유전물질이라는 근거를 설명하시오.","passage":null,"answer":"1952년 연구에서 DNA는 ³²P, 단백질은 ³⁵S로 표지했다. 감염 후 교반해 세균 표면의 파지 껍질을 분리하고 원심분리했다. 세균 침전에 ³²P가 주로 검출되고 ³⁵S는 주로 상층액에 남아, 세균 안에 들어가 증식을 지시한 물질이 DNA라는 근거를 얻었다.","wrong":[],"criteria":["두 표지 대응","교반·원심분리 목적","표지 분포와 DNA 결론"],"explanation":"","source_label":"박상영T 필기","source_page":3,"source_slide":null,"source_url":null,"sort":1042},{"id":"biology-park-depth-written-008","deck_id":"biology-park","kind":"written","topic":"심화 · 비분리와 염색체 이상","badge":null,"question":"한 염색체 쌍만 비분리한다는 조건에서 감수 1분열 비분리와 한 세포의 2분열 비분리가 만드는 네 생식세포를 비교하시오.","passage":null,"answer":"1분열에서 상동염색체가 분리되지 않고 2분열이 정상이라면 n+1 생식세포 두 개와 n−1 생식세포 두 개가 나온다. 1분열이 정상이고 두 세포 중 하나에서만 2분열 비분리가 일어나면 정상 n 두 개, n+1 한 개, n−1 한 개가 나온다.","wrong":[],"criteria":["각 분열의 분리 대상","1분열 비분리 산물","2분열 비분리 산물"],"explanation":"","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":1043},{"id":"biology-park-depth-written-009","deck_id":"biology-park","kind":"written","topic":"심화 · 비분리와 염색체 이상","badge":null,"question":"다운·에드워드·클라인펠터·터너의 대표 핵형 이상을 제시하고, 결실·역위 같은 구조 이상과 구별하시오.","passage":null,"answer":"대표적으로 다운은 21번 삼염색체, 에드워드는 18번 삼염색체, 클라인펠터는 47,XXY, 터너는 45,X다. 이들은 염색체 수 이상과 연결된다. 결실은 구간 소실, 역위는 구간 방향 반전이며 염색체 총수가 정상이어도 구조 이상이 있을 수 있다.","wrong":[],"criteria":["네 대표 수 이상","결실·역위 정의","염색체 수와 구조 구별"],"explanation":"","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":1044},{"id":"biology-park-depth-written-010","deck_id":"biology-park","kind":"written","topic":"심화 · 돌연변이 원인과 결과","badge":null,"question":"침묵·미스센스·넌센스와 읽는 틀 이동을 구별하고, 3염기 결실이 기능 정상임을 보장하지 않는 이유를 설명하시오.","passage":null,"answer":"침묵 치환은 지정 아미노산이 유지되고 미스센스는 다른 아미노산으로 바뀌며 넌센스는 종결 코돈을 만든다. 암호화 구간의 3의 배수가 아닌 삽입·결실은 뒤쪽 읽는 틀을 이동시킬 수 있다. 3염기 결실은 뒤쪽 틀을 유지해도 아미노산 소실 등으로 단백질 구조와 기능을 바꿀 수 있다.","wrong":[],"criteria":["세 치환 결과 구별","틀 이동의 3의 배수 조건","틀 유지와 기능 정상 구별"],"explanation":"","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":1045},{"id":"biology-park-depth-written-011","deck_id":"biology-park","kind":"written","topic":"심화 · 돌연변이 원인과 결과","badge":null,"question":"돌연변이의 자연발생·유발 원인을 각각 제시하고, 체세포 변이와 생식세포 변이의 전달 범위를 비교하시오.","passage":null,"answer":"자연발생 원인에는 복제 오류와 DNA 손상·수선 실패가 있고 유발 원인에는 자외선·방사선·일부 화학 물질이 있다. 체세포 변이는 해당 세포 계통으로 전달될 수 있다. 생식세포 계통의 변이는 그 생식세포가 수정에 참여하면 자손에게 전달될 수 있으며 우성 여부와는 별개다.","wrong":[],"criteria":["자연발생·유발 원인","체세포 계통 전달","수정에 참여한 생식세포 전달"],"explanation":"","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":1046},{"id":"biology-park-depth-written-012","deck_id":"biology-park","kind":"written","topic":"심화 · 사람의 유전 자료 해석","badge":null,"question":"ABO IᴬIᴮ인 사람이 Hh일 때와 hh일 때를 비교하고, H/h가 ABO 대립유전자 하나씩을 개별적으로 조절한다는 주장을 평가하시오.","passage":null,"answer":"H 좌위가 Hh면 기능하는 H가 H 항원 형성을 가능하게 하여 Iᴬ와 Iᴮ의 산물이 A·B 항원을 만들 수 있다. hh에서는 H 항원 형성이 제한돼 봄베이 표현형이 나타날 수 있다. H/h는 각각 Iᴬ와 Iᴮ에 붙어 한쪽 항원만 켜고 끄는 관계가 아니므로 그 주장은 옳지 않다.","wrong":[],"criteria":["Hh에서 H 항원과 A·B 형성","hh와 봄베이 표현형","한 대립유전자씩 대응한다는 주장 반박"],"explanation":"","source_label":"박상영T 필기","source_page":2,"source_slide":null,"source_url":null,"sort":1047},{"id":"chemistry-depth-001","deck_id":"chemistry","kind":"choice","topic":"화학 평형 · K·Q·이동","badge":"화학 · 적용","question":"밀폐 용기의 가역 반응이 평형이다. 반드시 성립하는 관계는?","passage":null,"answer":"정반응 속도=역반응 속도","wrong":["모든 물질의 농도가 같다","반응물과 생성물 양이 항상 같다","분자 사이 반응이 모두 멈춘다"],"criteria":[],"explanation":"동적 평형에서는 두 반응이 계속 진행하면서 속도가 같아 각 농도가 일정하다. 농도 값이 서로 같아야 하는 것은 아니다.","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":0},{"id":"chemistry-depth-002","deck_id":"chemistry","kind":"choice","topic":"화학 평형 · K·Q·이동","badge":"화학 · 적용","question":"A+2B⇌C의 평형 상수 식은? 모두 수용액이다.","passage":null,"answer":"[C]/([A][B]²)","wrong":["[C]²/([A][B])","[A][B]²/[C]","[C]/([A]+2[B])"],"criteria":[],"explanation":"농도 항의 지수는 반응식 계수다. 생성물 항을 반응물 항으로 나누며 B의 계수 2는 제곱에 반영한다.","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":1},{"id":"chemistry-depth-003","deck_id":"chemistry","kind":"choice","topic":"화학 평형 · K·Q·이동","badge":"화학 · 적용","question":"CaCO₃(s)⇌CaO(s)+CO₂(g)의 농도로 나타낸 평형 상수는?","passage":null,"answer":"[CO₂]","wrong":["1/[CO₂]","[CaCO₃]/[CaO]","[CaO][CO₂]/[CaCO₃]"],"criteria":[],"explanation":"순수한 고체 CaCO₃와 CaO의 활동도는 일정하여 농도 평형 상수 식에 넣지 않는다. 기체 CO₂ 항만 남는다.","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":2},{"id":"chemistry-depth-004","deck_id":"chemistry","kind":"choice","topic":"화학 평형 · K·Q·이동","badge":"화학 · 적용","question":"A⇌B의 K=4이며 현재 [A]=0.5 M, [B]=1 M이다. 반응 방향은?","passage":null,"answer":"정반응 우세","wrong":["역반응 우세","이미 평형","농도만으로 Q 계산 불가"],"criteria":[],"explanation":"Q=[B]/[A]=2로 K=4보다 작다. 생성물 B가 늘어 Q가 커지는 정반응 방향으로 진행한다.","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":3},{"id":"chemistry-depth-005","deck_id":"chemistry","kind":"choice","topic":"화학 평형 · K·Q·이동","badge":"화학 · 적용","question":"A⇌B의 K=2이고 Q=5다. 평형에 접근하는 동안의 변화는?","passage":null,"answer":"B 감소·A 증가","wrong":["B 증가·A 감소","둘 다 반드시 증가","두 농도가 즉시 같아짐"],"criteria":[],"explanation":"Q>K이므로 역반응이 우세하여 생성물이 줄고 반응물이 늘어난다. 평형에서 농도가 같아지는 것은 아니다.","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":4},{"id":"chemistry-depth-006","deck_id":"chemistry","kind":"choice","topic":"화학 평형 · K·Q·이동","badge":"화학 · 적용","question":"2A⇌B의 K=8이다. 반응식을 B⇌2A로 뒤집으면 K는?","passage":null,"answer":"1/8","wrong":["64","8","4"],"criteria":[],"explanation":"역반응의 평형 상수는 원래 상수의 역수다. 모든 농도 항의 분자와 분모가 바뀌기 때문이다.","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":5},{"id":"chemistry-depth-007","deck_id":"chemistry","kind":"choice","topic":"화학 평형 · K·Q·이동","badge":"화학 · 적용","question":"A⇌B의 K=3이다. 반응식을 2A⇌2B로 쓰면 K는?","passage":null,"answer":"9","wrong":["6","1/3","3"],"criteria":[],"explanation":"반응식 계수를 2배로 하면 농도 항의 지수도 2배가 되어 평형 상수는 K²=9다.","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":6},{"id":"chemistry-depth-008","deck_id":"chemistry","kind":"choice","topic":"화학 평형 · K·Q·이동","badge":"화학 · 적용","question":"같은 온도에서 평형 혼합물에 촉매만 넣었다. 최종 평형 상수는?","passage":null,"answer":"변하지 않는다","wrong":["항상 증가한다","항상 감소한다","반드시 1이 된다"],"criteria":[],"explanation":"촉매는 정·역반응의 경로를 바꾸어 평형에 빠르게 도달하게 하지만 일정 온도의 평형 상수는 바꾸지 않는다.","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":7},{"id":"chemistry-depth-009","deck_id":"chemistry","kind":"choice","topic":"화학 평형 · K·Q·이동","badge":"화학 · 적용","question":"N₂(g)+3H₂(g)⇌2NH₃(g)의 평형에서 온도를 유지하고 부피를 줄였다. 이동 방향은?","passage":null,"answer":"NH₃ 생성 방향","wrong":["N₂·H₂ 생성 방향","기체 몰수와 무관하게 정지","K가 반드시 증가하는 방향"],"criteria":[],"explanation":"기체 총 몰수가 4에서 2로 줄어드는 정반응 쪽으로 이동한다. 압력 변화 자체는 일정 온도의 K를 바꾸지 않는다.","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":8},{"id":"chemistry-depth-010","deck_id":"chemistry","kind":"choice","topic":"화학 평형 · K·Q·이동","badge":"화학 · 적용","question":"발열 정반응의 평형에서 온도를 올렸다. 새 평형에서 K의 변화는?","passage":null,"answer":"감소한다","wrong":["온도는 K에 영향을 주지 않는다","증가한다","항상 1이 된다"],"criteria":[],"explanation":"열을 생성물처럼 보면 가열은 역반응을 유리하게 한다. 발열 정반응의 생성물 비가 줄어 K가 감소한다.","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":9},{"id":"chemistry-depth-011","deck_id":"chemistry","kind":"choice","topic":"평형 실험 · 색 변화와 조작","badge":"화학 · 적용","question":"Cr₂O₇²⁻(주황)+H₂O⇌2CrO₄²⁻(노랑)+2H⁺에 HCl을 소량 넣었다. 대표적 색 변화는?","passage":null,"answer":"주황 쪽","wrong":["항상 무색","항상 파랑","노랑 쪽"],"criteria":[],"explanation":"H⁺ 증가를 줄이는 역반응이 유리해져 주황색 다이크로뮴산 이온 비율이 증가한다. 염화 이온 효과와 H⁺ 효과를 구별한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":10},{"id":"chemistry-depth-012","deck_id":"chemistry","kind":"choice","topic":"평형 실험 · 색 변화와 조작","badge":"화학 · 적용","question":"Cr₂O₇²⁻(주황)+H₂O⇌2CrO₄²⁻(노랑)+2H⁺에 NaOH를 소량 넣었다. 설명은?","passage":null,"answer":"H⁺ 소비로 노랑 쪽 이동","wrong":["OH⁻가 H⁺를 생성해 주황 이동","Na⁺가 직접 파란 착물을 형성","온도 일정해도 K가 반드시 증가"],"criteria":[],"explanation":"OH⁻가 H⁺와 반응하여 그 농도를 낮추므로 H⁺를 만드는 정반응이 유리해지고 노랑색 크로뮴산 이온이 증가한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":11},{"id":"chemistry-depth-013","deck_id":"chemistry","kind":"choice","topic":"평형 실험 · 색 변화와 조작","badge":"화학 · 적용","question":"분홍 코발트 착물+4Cl⁻⇌파랑 코발트 착물+6H₂O. CaCl₂를 넣을 때 핵심 조작 변수는?","passage":null,"answer":"Cl⁻ 농도 증가","wrong":["H⁺ 농도만 증가","온도만 감소","기체 압력 증가"],"criteria":[],"explanation":"CaCl₂는 용해되어 염화 이온을 공급한다. 공통 반응물 Cl⁻의 증가로 파랑 착물 생성 방향이 유리해진다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":12},{"id":"chemistry-depth-014","deck_id":"chemistry","kind":"choice","topic":"평형 실험 · 색 변화와 조작","badge":"화학 · 적용","question":"분홍 코발트 착물+4Cl⁻⇌파랑 코발트 착물+6H₂O. 물로 희석할 때 분홍 쪽으로 이동하는 설명은?","passage":null,"answer":"이온 농도 감소로 Q가 커진다","wrong":["흡열 반응이므로 항상 파랑이 된다","순수한 물 항만 K를 바꾼다","염화 이온 농도가 증가한다"],"criteria":[],"explanation":"물의 활동도를 일정하게 근사하면 Q=[파랑]/([분홍][Cl⁻]⁴)다. 같은 비율 희석에서 Q가 커져 역반응으로 분홍 쪽을 유리하게 한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":13},{"id":"chemistry-depth-015","deck_id":"chemistry","kind":"choice","topic":"평형 실험 · 색 변화와 조작","badge":"화학 · 적용","question":"분홍 코발트 착물⇌파랑 코발트 착물의 정반응이 흡열이다. 가열·냉각 결과는?","passage":null,"answer":"가열 파랑·냉각 분홍","wrong":["두 경우 모두 파랑","두 경우 모두 무색","가열 분홍·냉각 파랑"],"criteria":[],"explanation":"가열은 열을 소비하는 정반응, 냉각은 열을 내는 역반응을 유리하게 한다. 농도 조작과 다르게 온도는 K에도 영향을 준다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":14},{"id":"chemistry-depth-016","deck_id":"chemistry","kind":"choice","topic":"평형 실험 · 색 변화와 조작","badge":"화학 · 적용","question":"코발트 평형을 Cl⁻ 첨가와 가열로 각각 파랑 쪽으로 이동시켰다. K를 바꿀 수 있는 조작은?","passage":null,"answer":"가열","wrong":["Cl⁻ 첨가만","두 조작 모두 반드시 같다","둘 다 K를 바꾸지 않는다"],"criteria":[],"explanation":"같은 온도의 농도 조작은 Q와 조성을 바꾸지만 K는 유지한다. 가열은 온도를 바꾸므로 K도 바뀔 수 있다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":15},{"id":"chemistry-depth-017","deck_id":"chemistry","kind":"choice","topic":"평형 실험 · 색 변화와 조작","badge":"화학 · 적용","question":"주황↔노랑 평형 실험에서 산·염기를 번갈아 넣어 색 변화가 되돌아왔다. 보여 주는 성질은?","passage":null,"answer":"조건 변화에 따른 가역적 평형 이동","wrong":["생성물이 완전히 사라지는 비가역성","정반응만 존재한다는 사실","산·염기 첨가가 온도와 같다는 사실"],"criteria":[],"explanation":"관찰된 가역적 색 변화는 농도 조건을 바꾸면 평형 조성이 달라질 수 있음을 보여 준다. 색만으로 모든 물질의 소실을 단정하지 않는다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":16},{"id":"chemistry-depth-018","deck_id":"chemistry","kind":"choice","topic":"평형 실험 · 색 변화와 조작","badge":"화학 · 적용","question":"따뜻한 물과 얼음물에 같은 코발트 용액을 넣어 색을 비교한다. 공정한 비교 조건은?","passage":null,"answer":"초기 농도·부피를 같게 한다","wrong":["두 용액의 색이 달라야만 시작한다","한쪽에만 CaCl₂도 넣는다","한쪽 초기 농도를 10배로 한다"],"criteria":[],"explanation":"온도의 영향을 비교하려면 초기 농도와 부피 등 다른 조건을 같게 하고 충분히 온도가 안정된 뒤 관찰해야 한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":17},{"id":"chemistry-depth-019","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"NH₃+H₂O⇌NH₄⁺+OH⁻에서 물의 역할은?","passage":null,"answer":"H⁺를 주는 산","wrong":["아무 변화 없는 촉매","항상 산도 염기도 아님","H⁺를 받는 염기"],"criteria":[],"explanation":"물은 NH₃에 양성자를 주고 OH⁻가 되므로 이 반응에서 브뢴스테드·로리 산이다. 물의 역할은 반응마다 달라질 수 있다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":18},{"id":"chemistry-depth-020","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"HCl+H₂O→H₃O⁺+Cl⁻에서 물의 역할은?","passage":null,"answer":"H⁺를 받는 염기","wrong":["H⁺를 주는 산","전자만 받는 산","염화 이온을 주는 염기"],"criteria":[],"explanation":"물은 HCl의 양성자를 받아 H₃O⁺가 되므로 염기다. 물은 다른 반응에서 산으로도 작용할 수 있다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":19},{"id":"chemistry-depth-021","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"짝산·짝염기 관계인 것은?","passage":null,"answer":"H₂CO₃와 HCO₃⁻","wrong":["HCl과 NaOH","H₃O⁺와 OH⁻","CH₃COOH와 Na⁺"],"criteria":[],"explanation":"짝산·짝염기는 양성자 한 개만 차이난다. H₂CO₃에서 H⁺를 하나 떼면 HCO₃⁻다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":20},{"id":"chemistry-depth-022","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"같은 온도에서 Ka(A)=10⁻³, Ka(B)=10⁻⁶이다. 산과 짝염기의 세기는?","passage":null,"answer":"A가 강산·B의 짝염기가 더 강함","wrong":["산의 세기와 짝염기 세기는 비례","B가 강산·A의 짝염기가 더 강함","A와 B의 세기가 같다"],"criteria":[],"explanation":"Ka가 클수록 산의 이온화 경향이 크다. KaKb=Kw이므로 강한 산의 짝염기는 더 약하다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":21},{"id":"chemistry-depth-023","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"25℃에서 [H₃O⁺]=10⁻⁴ M인 용액의 pH와 [OH⁻]는?","passage":null,"answer":"4·10⁻¹⁰ M","wrong":["4·10⁻⁴ M","10·10⁻¹⁰ M","10·10⁻⁴ M"],"criteria":[],"explanation":"pH=−log[H₃O⁺]=4이고 Kw=10⁻¹⁴=[H₃O⁺][OH⁻]에서 [OH⁻]=10⁻¹⁰ M다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":22},{"id":"chemistry-depth-024","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"25℃에서 [OH⁻]=10⁻³ M일 때 pH는?","passage":null,"answer":"11","wrong":["3","7","14"],"criteria":[],"explanation":"pOH=3이며 pH+pOH=14이므로 pH=11이다. OH⁻를 H₃O⁺처럼 바로 pH 식에 넣지 않는다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":23},{"id":"chemistry-depth-025","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"같은 온도에서 pH 3과 pH 5 용액의 H₃O⁺ 농도 비는?","passage":null,"answer":"100:1","wrong":["2:1","1:100","5:3"],"criteria":[],"explanation":"pH 3은 10⁻³ M, pH 5는 10⁻⁵ M이므로 100:1이다. pH의 차이를 농도의 단순 차이로 해석하지 않는다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":24},{"id":"chemistry-depth-026","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"0.01 M HCl과 0.10 M CH₃COOH를 비교한다. 강약·농도 구별은?","passage":null,"answer":"HCl이 강산·아세트산이 더 진함","wrong":["두 용액의 강약과 농도 모두 같음","아세트산이 강산·HCl이 더 진함","농도가 큰 산이 항상 강산"],"criteria":[],"explanation":"HCl은 거의 완전히 이온화하는 강산이고 아세트산은 약산이다. 분석 농도는 아세트산이 10배이며 강약과 농도를 구별한다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":25},{"id":"chemistry-depth-027","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"약산 HA의 초기 농도 C, 이온화량 x다. 물의 이온화를 무시할 때 정확한 식은?","passage":null,"answer":"Ka=x²/(C−x)","wrong":["Ka=(C−x)²/x","Ka=C/x²","Ka=x²/C만 항상 정확"],"criteria":[],"explanation":"평형 [HA]=C−x, [H₃O⁺]=[A⁻]=x이므로 Ka=x²/(C−x)다. C−x≈C는 x/C가 작을 때만 근사다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":26},{"id":"chemistry-depth-028","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"0.10 M 약산에서 근사 계산 x=0.0020 M을 얻었다. 5% 규칙 적용 결과는?","passage":null,"answer":"2%이므로 근사 타당","wrong":["20%이므로 근사 불가","0.2%이므로 정확해와 동일","5% 규칙은 강산에만 적용"],"criteria":[],"explanation":"x/C×100=0.0020/0.10×100=2%다. 5% 이하이면 이 기준에서 근사 사용이 타당하며 정확해와 완전히 같다는 뜻은 아니다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":27},{"id":"chemistry-depth-029","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"0.010 M 약산의 근사 x=0.0030 M이다. 다음 계산으로 적절한 것은?","passage":null,"answer":"근사 재검토 후 이차식으로 계산","wrong":["30%라도 분모를 C로 둔다","pH는 항상 7로 둔다","Ka 대신 Kp를 꼭 사용한다"],"criteria":[],"explanation":"이온화율이 30%로 5%를 넘으므로 C−x≈C가 부적절하다. 정확한 Ka=x²/(C−x)로 풀어야 한다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":28},{"id":"chemistry-depth-030","deck_id":"chemistry","kind":"choice","topic":"산·염기 · 짝과 세기·pH","badge":"화학 · 적용","question":"25℃에서 Ka=10⁻⁵인 산의 짝염기 Kb는?","passage":null,"answer":"10⁻⁹","wrong":["10⁹","10⁻⁵","10⁻¹⁴"],"criteria":[],"explanation":"KaKb=Kw=10⁻¹⁴이므로 Kb=10⁻¹⁴/10⁻⁵=10⁻⁹다. 같은 온도의 짝 관계에 적용한다.","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":29},{"id":"chemistry-depth-031","deck_id":"chemistry","kind":"choice","topic":"중화 반응 · 몰수·희석·혼합","badge":"화학 · 적용","question":"0.20 M HCl 50 mL를 완전 중화하는 0.10 M Ca(OH)₂의 부피는?","passage":null,"answer":"50 mL","wrong":["25 mL","200 mL","100 mL"],"criteria":[],"explanation":"H⁺는 0.20×0.050=0.010 mol이다. Ca(OH)₂ 한 몰은 OH⁻ 두 몰이므로 2×0.10×V=0.010에서 V=0.050 L다.","source_label":"Ⅰ-0. 화학 중화반응","source_page":3,"source_slide":null,"source_url":null,"sort":30},{"id":"chemistry-depth-032","deck_id":"chemistry","kind":"choice","topic":"중화 반응 · 몰수·희석·혼합","badge":"화학 · 적용","question":"0.10 M H₂SO₄ 30 mL를 완전 중화하는 0.10 M NaOH는? 두 양성자가 모두 반응한다.","passage":null,"answer":"60 mL","wrong":["30 mL","15 mL","90 mL"],"criteria":[],"explanation":"산의 반응 양성자 몰수는 2×0.10×0.030=0.006 mol이다. NaOH 0.10 M는 0.060 L가 필요하다.","source_label":"Ⅰ-0. 화학 중화반응","source_page":3,"source_slide":null,"source_url":null,"sort":31},{"id":"chemistry-depth-033","deck_id":"chemistry","kind":"choice","topic":"중화 반응 · 몰수·희석·혼합","badge":"화학 · 적용","question":"25℃에서 0.10 M HCl 20 mL와 0.10 M NaOH 10 mL를 혼합했다. 부피가 합쳐질 때 남은 H⁺ 농도는?","passage":null,"answer":"1/30 M","wrong":["0.10 M","1/10 M","1/60 M"],"criteria":[],"explanation":"H⁺ 0.002 mol에서 OH⁻ 0.001 mol을 빼면 0.001 mol이 남는다. 전체 0.030 L로 나누면 1/30 M다.","source_label":"Ⅰ-0. 화학 중화반응","source_page":3,"source_slide":null,"source_url":null,"sort":32},{"id":"chemistry-depth-034","deck_id":"chemistry","kind":"choice","topic":"중화 반응 · 몰수·희석·혼합","badge":"화학 · 적용","question":"25℃에서 0.10 M HCl 10 mL와 0.10 M NaOH 30 mL를 혼합했다. 남은 OH⁻ 농도는?","passage":null,"answer":"0.050 M","wrong":["0.20 M","0.10 M","0.025 M"],"criteria":[],"explanation":"OH⁻ 0.003 mol에서 H⁺ 0.001 mol을 빼면 0.002 mol이 남는다. 전체 0.040 L로 나누면 0.050 M다.","source_label":"Ⅰ-0. 화학 중화반응","source_page":3,"source_slide":null,"source_url":null,"sort":33},{"id":"chemistry-depth-035","deck_id":"chemistry","kind":"choice","topic":"중화 반응 · 몰수·희석·혼합","badge":"화학 · 적용","question":"산 시료 20 mL를 정량 취한 뒤 증류수 30 mL를 추가하고 적정했다. 필요한 NaOH 몰수는?","passage":null,"answer":"물 추가 전과 같다","wrong":["2.5배로 감소","산이 약산이면 반드시 0","2.5배로 증가"],"criteria":[],"explanation":"정량 취한 산 시료의 산 몰수는 물 추가로 바뀌지 않는다. 같은 산 몰수를 중화하므로 필요한 NaOH 몰수도 같다.","source_label":"Ⅰ-0. 화학 중화반응","source_page":3,"source_slide":null,"source_url":null,"sort":34},{"id":"chemistry-depth-036","deck_id":"chemistry","kind":"choice","topic":"중화 반응 · 몰수·희석·혼합","badge":"화학 · 적용","question":"원액 10 mL를 물로 최종 100 mL로 희석했다. 같은 원액의 농도를 C라 할 때 희석액 농도는?","passage":null,"answer":"C/10","wrong":["10C","C","C/100"],"criteria":[],"explanation":"용질 몰수 C×10 mL가 최종 100 mL에 분포하므로 C/10이다. 물을 100 mL 더 넣는 조건과 구별한다.","source_label":"Ⅰ-0. 화학 중화반응","source_page":3,"source_slide":null,"source_url":null,"sort":35},{"id":"chemistry-depth-037","deck_id":"chemistry","kind":"choice","topic":"중화 반응 · 몰수·희석·혼합","badge":"화학 · 적용","question":"0.10 M HCl과 0.10 M NaOH를 같은 부피 섞었다. 25℃에서 이상적으로 중화점의 pH는?","passage":null,"answer":"7","wrong":["1","13","강산이므로 항상 1"],"criteria":[],"explanation":"강산·강염기의 같은 반응 몰수라면 염의 가수분해 효과를 무시할 수 있어 25℃에서 중성 pH 7이다.","source_label":"Ⅰ-0. 화학 중화반응","source_page":3,"source_slide":null,"source_url":null,"sort":36},{"id":"chemistry-depth-038","deck_id":"chemistry","kind":"choice","topic":"중화 반응 · 몰수·희석·혼합","badge":"화학 · 적용","question":"중화점의 정의로 타당한 것은?","passage":null,"answer":"산·염기가 화학량론적으로 반응한 점","wrong":["모든 이온이 완전히 없어진 점","어떤 산·염기라도 pH가 7인 점","지시약을 처음 넣는 순간"],"criteria":[],"explanation":"중화점은 반응식 계수에 맞는 산·염기 양이 반응한 점이다. 약산·강염기 중화점은 염기성일 수 있고 염 이온은 남아 있다.","source_label":"Ⅰ-0. 화학 중화반응","source_page":3,"source_slide":null,"source_url":null,"sort":37},{"id":"chemistry-depth-039","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"미지 아세트산 20.0 mL에 0.100 M NaOH 22.0 mL가 정확히 중화량이었다. 산 몰농도는?","passage":null,"answer":"0.110 M","wrong":["0.220 M","1.10 M","0.0909 M"],"criteria":[],"explanation":"아세트산과 NaOH는 1:1 반응이다. 0.100×0.0220/0.0200=0.110 M이며 mL 비는 서로 약분 가능하다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":38},{"id":"chemistry-depth-040","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"뷰렛 초기 1.20 mL, 최종 23.40 mL다. 사용량은?","passage":null,"answer":"22.20 mL","wrong":["23.40 mL","24.60 mL","1.20 mL"],"criteria":[],"explanation":"사용량은 최종−초기=23.40−1.20=22.20 mL다. 초기 눈금이 0이 아닐 때 최종값만 쓰면 과대 계산한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":39},{"id":"chemistry-depth-041","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"미지 산 적정에서 종말점을 지나 NaOH를 과량 넣고 그대로 사용량을 기록했다. 계산한 산 농도는?","passage":null,"answer":"과대","wrong":["과소","항상 정확","과대·과소가 상쇄되어 동일"],"criteria":[],"explanation":"산 농도를 표준 NaOH 사용 몰수로 계산하므로 기록한 사용량이 커지면 산 몰수와 농도를 과대 추정한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":40},{"id":"chemistry-depth-042","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"NaOH로 헹구지 않은 뷰렛의 잔류 물이 표준 NaOH를 희석했다. 원래 농도로 산을 계산하면?","passage":null,"answer":"산 농도를 과대 추정","wrong":["중화가 더 빨라져 과소 추정","산 농도를 과소 추정","산 농도에는 영향 없음"],"criteria":[],"explanation":"실제 NaOH 농도가 낮아 같은 산에 더 큰 부피가 필요하다. 이를 더 높은 원래 농도로 곱하면 산 몰수를 과대 계산한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":41},{"id":"chemistry-depth-043","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"산으로 헹구지 않은 피펫의 잔류 물이 정량 취한 시료를 희석했다. 원액 농도 계산의 영향은?","passage":null,"answer":"과소 추정","wrong":["항상 영향 없음","뷰렛 사용량이 더 커져 과대","과대 추정"],"criteria":[],"explanation":"피펫의 정해진 부피에 포함된 실제 산 몰수가 줄어 NaOH 사용량이 감소한다. 원액의 해당 부피에 들어 있을 몰수를 작게 추정한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":42},{"id":"chemistry-depth-044","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"산을 정량 취한 삼각 플라스크에 증류수 몇 방울이 남아 있다. 적정으로 구한 원액 농도는?","passage":null,"answer":"이상적 조건에서 영향 없음","wrong":["항상 과소 추정","항상 과대 추정","산이 강산이면 2배"],"criteria":[],"explanation":"정량 취한 산의 몰수는 플라스크의 물로 바뀌지 않는다. 피펫 속 물 때문에 취한 산 몰수가 줄어드는 경우와 구별한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":43},{"id":"chemistry-depth-045","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"뷰렛 끝에 있던 기포가 적정 중 사라져 눈금 변화 일부가 끝부분을 채웠다. 기록 사용량으로 계산한 산 농도는?","passage":null,"answer":"과대 추정","wrong":["과소 추정","변화 없음","반드시 정확히 2배"],"criteria":[],"explanation":"눈금 변화에는 플라스크에 도달하지 않고 끝을 채운 부피도 포함된다. 사용량을 과대 기록하므로 산 농도도 과대 추정한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":44},{"id":"chemistry-depth-046","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"중화점 근처에서 NaOH 첨가 간격을 1 mL에서 0.1 mL로 줄이는 주된 이유는?","passage":null,"answer":"급격한 pH 변화 구간을 자세히 찾기","wrong":["중화점을 pH 7로 고정하기","NaOH의 농도를 증가시키기","중화 반응 계수를 바꾸기"],"criteria":[],"explanation":"중화점 부근에서는 적은 첨가량에도 pH가 급변한다. 작은 간격은 위치를 자세히 추정하게 하며 표준용액 농도를 바꾸지 않는다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":45},{"id":"chemistry-depth-047","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"pH 센서 값을 기록하기 전에 충분히 저으며 안정될 때까지 기다리는 까닭은?","passage":null,"answer":"국소 농도·응답 지연 영향을 줄인다","wrong":["모든 용액을 pH 7로 만든다","중화점의 산 몰수를 감소시킨다","산의 총 몰수를 늘린다"],"criteria":[],"explanation":"용액이 섞이지 않으면 국소 pH를 읽을 수 있고 센서에는 응답 시간이 있다. 충분한 혼합과 안정 후 기록이 필요하다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":46},{"id":"chemistry-depth-048","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"센서로 그린 적정 곡선의 축을 올바르게 정한 것은?","passage":null,"answer":"x: NaOH 부피·y: pH","wrong":["x: pH·y: 시간만","x: 산의 초기 부피·y: pH","x: NaOH 농도·y: 항상 온도"],"criteria":[],"explanation":"수업의 적정 곡선은 첨가한 NaOH의 누적 부피에 따른 pH 변화다. 사용량과 부피 간격을 구분한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":47},{"id":"chemistry-depth-049","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"지시약 종말점과 화학량론적 중화점의 관계는?","passage":null,"answer":"가까울 수 있지만 항상 같지는 않다","wrong":["어떤 지시약에서도 항상 같다","종말점은 항상 pH 7이다","중화점에는 지시약이 필수다"],"criteria":[],"explanation":"지시약의 변색 범위와 실제 중화점은 다를 수 있다. 급격한 pH 변화 구간에 맞는 지시약을 선택해야 오차가 작다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":48},{"id":"chemistry-depth-050","deck_id":"chemistry","kind":"choice","topic":"적정 실험 · 그래프와 오차","badge":"화학 · 적용","question":"10배 희석한 식초 20 mL 적정에 0.10 M NaOH 16 mL가 들었다. 원래 식초의 아세트산 농도는?","passage":null,"answer":"0.80 M","wrong":["8.0 M","0.080 M","0.0080 M"],"criteria":[],"explanation":"희석액 농도는 0.10×16/20=0.080 M다. 원액은 10배이므로 0.80 M이며 희석 배수를 다시 반영한다.","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":49},{"id":"chemistry-depth-051","deck_id":"chemistry","kind":"choice","topic":"염의 가수분해 · 중화점 pH","badge":"화학 · 적용","question":"25℃에서 CH₃COOH를 NaOH로 적정한 중화점의 pH는?","passage":null,"answer":"7보다 크다","wrong":["7보다 작다","초기 산 pH와 같다","항상 7"],"criteria":[],"explanation":"생성된 CH₃COO⁻가 물에서 OH⁻를 만들어 염기성을 나타낸다. 화학량론적 중화점과 중성 pH를 구별한다.","source_label":"Ⅰ-3. 중화적정","source_page":17,"source_slide":null,"source_url":null,"sort":50},{"id":"chemistry-depth-052","deck_id":"chemistry","kind":"choice","topic":"염의 가수분해 · 중화점 pH","badge":"화학 · 적용","question":"25℃에서 NH₃를 HCl로 적정한 중화점이 산성인 주된 까닭은?","passage":null,"answer":"NH₄⁺가 물에 H⁺를 준다","wrong":["Cl⁻가 강염기로 작용한다","중화 후 남은 NH₃만이 산으로 작용","염이 전혀 생성되지 않는다"],"criteria":[],"explanation":"NH₄⁺는 약염기 NH₃의 짝산으로 물과 반응하여 H₃O⁺를 형성한다. Cl⁻의 효과는 보통 무시한다.","source_label":"Ⅰ-3. 중화적정","source_page":17,"source_slide":null,"source_url":null,"sort":51},{"id":"chemistry-depth-053","deck_id":"chemistry","kind":"choice","topic":"염의 가수분해 · 중화점 pH","badge":"화학 · 적용","question":"같은 농도의 NaCl과 CH₃COONa 용액을 25℃에서 비교하면?","passage":null,"answer":"NaCl 중성·CH₃COONa 염기성","wrong":["둘 다 같은 산성","둘 다 항상 pH 7","NaCl 염기성·CH₃COONa 중성"],"criteria":[],"explanation":"강산·강염기 유래 NaCl의 가수분해는 무시할 수 있다. 아세트산 이온은 물과 반응해 OH⁻를 생성한다.","source_label":"Ⅰ-3. 중화적정","source_page":17,"source_slide":null,"source_url":null,"sort":52},{"id":"chemistry-depth-054","deck_id":"chemistry","kind":"choice","topic":"염의 가수분해 · 중화점 pH","badge":"화학 · 적용","question":"약산 HA 0.10 M 20 mL를 0.10 M NaOH로 적정했다. 중화량은?","passage":null,"answer":"20 mL","wrong":["Ka가 없으면 계산 불가","Ka가 작으면 반드시 10 mL","초기 H⁺만큼인 극소량"],"criteria":[],"explanation":"단양성자 약산의 전체 HA가 반응하므로 0.002 mol에 해당하는 NaOH 20 mL가 필요하다. 초기 자유 H⁺만 세지 않는다.","source_label":"Ⅰ-3. 중화적정","source_page":17,"source_slide":null,"source_url":null,"sort":53},{"id":"chemistry-depth-055","deck_id":"chemistry","kind":"choice","topic":"염의 가수분해 · 중화점 pH","badge":"화학 · 적용","question":"CH₃COOH와 NaOH의 중화점에서 CH₃COO⁻ 농도 계산의 분모는?","passage":null,"answer":"산과 NaOH의 전체 부피","wrong":["NaOH 부피만","생성된 물의 부피만","초기 산 부피만"],"criteria":[],"explanation":"생성된 아세트산 이온 몰수가 혼합 전체 부피에 분포한다. 부피가 합쳐진다는 조건에서는 두 용액 부피를 더한다.","source_label":"Ⅰ-3. 중화적정","source_page":17,"source_slide":null,"source_url":null,"sort":54},{"id":"chemistry-depth-056","deck_id":"chemistry","kind":"choice","topic":"염의 가수분해 · 중화점 pH","badge":"화학 · 적용","question":"약산의 짝염기 A⁻가 물과 반응하는 식은?","passage":null,"answer":"A⁻+H₂O⇌HA+OH⁻","wrong":["A⁻+H₂O⇌HA+H₃O⁺","HA+OH⁻⇌A⁻+H₃O⁺","A⁻⇌A+전자"],"criteria":[],"explanation":"A⁻는 물에서 H⁺를 받아 HA가 되고 물은 OH⁻를 남긴다. 짝염기 가수분해와 산의 이온화 식을 구별한다.","source_label":"Ⅰ-3. 중화적정","source_page":17,"source_slide":null,"source_url":null,"sort":55},{"id":"chemistry-depth-057","deck_id":"chemistry","kind":"choice","topic":"완충 작용 · 원리와 실험 비교","badge":"화학 · 적용","question":"충분한 양의 두 성분으로 만든 전형적인 완충 조합은?","passage":null,"answer":"CH₃COOH와 CH₃COONa","wrong":["HCl과 NaCl","NaOH와 NaCl","HCl과 HNO₃"],"criteria":[],"explanation":"약산과 그 짝염기가 함께 있으면 첨가 H⁺와 OH⁻를 각각 소비한다. 강산과 그 염만 섞는 것은 전형적 완충계가 아니다.","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":56},{"id":"chemistry-depth-058","deck_id":"chemistry","kind":"choice","topic":"완충 작용 · 원리와 실험 비교","badge":"화학 · 적용","question":"아세트산/아세트산 이온 완충계에 소량 HCl을 넣었다. 주로 소비하는 성분은?","passage":null,"answer":"CH₃COO⁻","wrong":["용액 속 모든 OH⁻만","Na⁺","Cl⁻"],"criteria":[],"explanation":"CH₃COO⁻+H⁺→CH₃COOH로 첨가한 산을 소비한다. 약산/짝염기 비는 변하지만 pH 변화가 줄어든다.","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":57},{"id":"chemistry-depth-059","deck_id":"chemistry","kind":"choice","topic":"완충 작용 · 원리와 실험 비교","badge":"화학 · 적용","question":"아세트산/아세트산 이온 완충계에 소량 NaOH를 넣었다. 주로 소비하는 성분은?","passage":null,"answer":"CH₃COOH","wrong":["Cl⁻","CH₃COO⁻만","Na⁺"],"criteria":[],"explanation":"CH₃COOH+OH⁻→CH₃COO⁻+H₂O로 첨가한 염기를 소비한다. 짝염기만 있고 약산이 없다면 이 경로가 제한된다.","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":58},{"id":"chemistry-depth-060","deck_id":"chemistry","kind":"choice","topic":"완충 작용 · 원리와 실험 비교","badge":"화학 · 적용","question":"완충계의 HA 10 mmol, A⁻ 10 mmol에 HCl 2 mmol을 넣었다. 반응 후 양은?","passage":null,"answer":"HA 12·A⁻ 8 mmol","wrong":["HA 8·A⁻ 12 mmol","HA 10·A⁻ 12 mmol","HA 12·A⁻ 10 mmol"],"criteria":[],"explanation":"H⁺가 A⁻ 2 mmol을 소비하고 HA 2 mmol을 만든다. 첨가한 강산을 먼저 반응시킨 뒤 남은 완충 성분을 계산한다.","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":59},{"id":"chemistry-depth-061","deck_id":"chemistry","kind":"choice","topic":"완충 작용 · 원리와 실험 비교","badge":"화학 · 적용","question":"완충계의 HA 10 mmol, A⁻ 10 mmol에 NaOH 3 mmol을 넣었다. 반응 후 양은?","passage":null,"answer":"HA 7·A⁻ 13 mmol","wrong":["HA 13·A⁻ 7 mmol","HA 10·A⁻ 7 mmol","HA 13·A⁻ 10 mmol"],"criteria":[],"explanation":"OH⁻는 HA 3 mmol을 소비하고 A⁻ 3 mmol을 만든다. 양성자 이동과 몰수 보존을 함께 확인한다.","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":60},{"id":"chemistry-depth-062","deck_id":"chemistry","kind":"choice","topic":"완충 작용 · 원리와 실험 비교","badge":"화학 · 적용","question":"HA 1 mmol·A⁻ 1 mmol 완충계에 NaOH 3 mmol을 넣었다. 예상 결과는?","passage":null,"answer":"HA 소진 후 OH⁻가 남아 pH 급변","wrong":["HA가 4 mmol로 증가","원래 pH가 완전히 유지","A⁻가 OH⁻ 전부를 중화"],"criteria":[],"explanation":"HA가 소비할 수 있는 OH⁻는 1 mmol뿐이다. 2 mmol 과량 OH⁻가 남으므로 완충 용량을 넘어 pH가 크게 변한다.","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":61},{"id":"chemistry-depth-063","deck_id":"chemistry","kind":"choice","topic":"완충 작용 · 원리와 실험 비교","badge":"화학 · 적용","question":"같은 HA:A⁻ 비에서 총농도를 10배 낮추었다. 소량 첨가 전 pH와 완충 용량의 대표 변화는?","passage":null,"answer":"pH는 비슷·용량은 감소","wrong":["pH 동일·용량 10배 증가","비가 같으면 용량도 항상 같음","pH가 반드시 10배·용량 같음"],"criteria":[],"explanation":"적절한 완충 근사에서 pH는 성분 비에 좌우되어 비슷하지만 반응 가능한 몰수가 줄어 완충 용량은 낮아진다.","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":62},{"id":"chemistry-depth-064","deck_id":"chemistry","kind":"choice","topic":"완충 작용 · 원리와 실험 비교","badge":"화학 · 적용","question":"물·약산·짝염기·완충 혼합물에 같은 양의 산·염기를 넣는다. 완충성을 비교할 지표는?","passage":null,"answer":"첨가 전후 pH 변화의 크기","wrong":["처음 pH가 7인지 여부만","산과 염기를 넣은 순서만","초기 pH가 모두 같은지 여부"],"criteria":[],"explanation":"완충은 초기 pH가 7인지가 아니라 첨가에 따른 pH 변화가 작은 성질이다. 동일 첨가량·초기 부피 등을 통제한다.","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":63},{"id":"chemistry-depth-065","deck_id":"chemistry","kind":"choice","topic":"완충 작용 · 원리와 실험 비교","badge":"화학 · 적용","question":"HA의 Ka=[H⁺][A⁻]/[HA]다. 완충계에서 [HA]=[A⁻]이면?","passage":null,"answer":"[H⁺]≈Ka","wrong":["[H⁺]≈1/Ka","pH가 항상 7","[H⁺]가 반드시 0"],"criteria":[],"explanation":"같은 농도 비이면 식에서 [H⁺]≈Ka가 된다. 약산 종류마다 Ka가 다르므로 pH 7로 고정되는 것은 아니다.","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":64},{"id":"chemistry-depth-066","deck_id":"chemistry","kind":"choice","topic":"완충 작용 · 원리와 실험 비교","badge":"화학 · 적용","question":"아세트산/아세트산 이온 완충계에 소량 HCl을 넣었다. 원래 상태와 비교한 변화는?","passage":null,"answer":"A⁻/HA 감소·pH 소폭 감소","wrong":["HA 소멸·pH 반드시 14","A⁻/HA 증가·pH 소폭 증가","두 성분 양과 pH 모두 정확히 불변"],"criteria":[],"explanation":"A⁻가 H⁺를 받아 HA가 되므로 A⁻/HA가 감소한다. [H⁺]=Ka[HA]/[A⁻] 관계에서 H⁺가 늘어 pH가 소폭 낮아진다.","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":65},{"id":"chemistry-depth-067","deck_id":"chemistry","kind":"choice","topic":"계산 심화 · 평형·적정·완충 검산","badge":"화학 · 적용","question":"A⇌B에서 초기 [A]=1.0 M, [B]=0이고 평형 [B]=0.60 M이다. K는? 부피 일정.","passage":null,"answer":"1.5","wrong":["0.4","2.5","0.6"],"criteria":[],"explanation":"1:1 반응이므로 평형 [A]=1.0−0.60=0.40 M다. K=[B]/[A]=0.60/0.40=1.5다.","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":66},{"id":"chemistry-depth-068","deck_id":"chemistry","kind":"choice","topic":"계산 심화 · 평형·적정·완충 검산","badge":"화학 · 적용","question":"2A⇌B에서 초기 [A]=1.0 M, [B]=0이고 평형 [B]=0.20 M이다. 평형 [A]는?","passage":null,"answer":"0.60 M","wrong":["0.80 M","0.40 M","0.20 M"],"criteria":[],"explanation":"B 0.20 M 생성에는 A가 계수에 따라 0.40 M 감소한다. 남은 [A]=1.0−0.40=0.60 M다.","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":67},{"id":"chemistry-depth-069","deck_id":"chemistry","kind":"choice","topic":"계산 심화 · 평형·적정·완충 검산","badge":"화학 · 적용","question":"A+B⇌C의 평형 농도가 A 0.20 M, B 0.50 M, C 0.40 M다. K는?","passage":null,"answer":"4","wrong":["0.25","1.1","2"],"criteria":[],"explanation":"K=[C]/([A][B])=0.40/(0.20×0.50)=4다. 평형 농도를 반응식 계수의 지수로 대입한다.","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":68},{"id":"chemistry-depth-070","deck_id":"chemistry","kind":"choice","topic":"계산 심화 · 평형·적정·완충 검산","badge":"화학 · 적용","question":"A⇌B의 K=4이다. 초기 A 1.0 M만 넣은 일정 부피 용기에서 평형 [B]는?","passage":null,"answer":"0.80 M","wrong":["4.0 M","0.20 M","0.25 M"],"criteria":[],"explanation":"[B]=x이면 [A]=1−x다. x/(1−x)=4를 풀면 5x=4에서 x=0.80 M다.","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":69},{"id":"chemistry-depth-071","deck_id":"chemistry","kind":"choice","topic":"계산 심화 · 평형·적정·완충 검산","badge":"화학 · 적용","question":"HA 0.10 M, Ka=10⁻⁵에서 물 이온화를 무시하고 x≪C 근사한다. [H⁺]와 근사 이온화율은?","passage":null,"answer":"10⁻³ M·1%","wrong":["10⁻² M·10%","10⁻⁶ M·1%","10⁻⁵ M·0.01%"],"criteria":[],"explanation":"x≈√(KaC)=√10⁻⁶=10⁻³ M이고 x/C=0.01=1%다. 5% 기준에서도 근사가 타당하다.","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":70},{"id":"chemistry-depth-072","deck_id":"chemistry","kind":"choice","topic":"계산 심화 · 평형·적정·완충 검산","badge":"화학 · 적용","question":"25℃에서 [H⁺]=2×10⁻³ M이다. log₁₀2=0.301일 때 pH는?","passage":null,"answer":"2.699","wrong":["3.301","0.301","11.301"],"criteria":[],"explanation":"−log(2×10⁻³)=3−log2=2.699다. 계수 2의 로그를 생략하면 정확한 pH와 다르다.","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":71},{"id":"chemistry-depth-073","deck_id":"chemistry","kind":"choice","topic":"계산 심화 · 평형·적정·완충 검산","badge":"화학 · 적용","question":"NaOH 사용량 19.8, 20.0, 20.2 mL의 평균은? 세 값 모두 유효하다.","passage":null,"answer":"20.0 mL","wrong":["20.2 mL","19.8 mL","60.0 mL"],"criteria":[],"explanation":"세 값의 합 60.0 mL를 3으로 나누면 20.0 mL다. 유효한 반복값을 평균하고 이상치 여부는 별도 기준으로 판단한다.","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":72},{"id":"chemistry-depth-074","deck_id":"chemistry","kind":"choice","topic":"계산 심화 · 평형·적정·완충 검산","badge":"화학 · 적용","question":"아세트산 원액 농도 0.80 M, 몰질량 60 g/mol, 밀도 1.0 g/mL다. 질량 백분율은?","passage":null,"answer":"4.8%","wrong":["8.0%","48%","0.48%"],"criteria":[],"explanation":"1 L 용액의 질량은 1000 g이고 아세트산은 0.80×60=48 g이다. 48/1000×100=4.8%다.","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":73},{"id":"chemistry-depth-075","deck_id":"chemistry","kind":"choice","topic":"계산 심화 · 평형·적정·완충 검산","badge":"화학 · 적용","question":"25℃에서 0.10 M HCl 10 mL에 0.10 M NaOH 20 mL를 넣었다. 남은 OH⁻ 농도는?","passage":null,"answer":"1/30 M","wrong":["1/20 M","1/10 M","0.10 M"],"criteria":[],"explanation":"OH⁻ 과량은 0.002−0.001=0.001 mol이다. 전체 0.030 L로 나누면 1/30 M다.","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":74},{"id":"chemistry-depth-076","deck_id":"chemistry","kind":"choice","topic":"계산 심화 · 평형·적정·완충 검산","badge":"화학 · 적용","question":"완충계 Ka=10⁻⁵, [HA]/[A⁻]=2다. 주어진 Ka 관계에서 [H⁺]는?","passage":null,"answer":"2×10⁻⁵ M","wrong":["5×10⁻⁶ M","10⁻⁵ M","2×10⁵ M"],"criteria":[],"explanation":"Ka=[H⁺][A⁻]/[HA]이므로 [H⁺]=Ka[HA]/[A⁻]=2×10⁻⁵ M다. 비를 뒤집으면 반대 결과가 나온다.","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":75},{"id":"chemistry-depth-written-001","deck_id":"chemistry","kind":"written","topic":"화학 평형 · K·Q·이동","badge":null,"question":"평형에서 농도가 일정하지만 반응이 멈추지 않는 이유를 설명하고, 촉매와 온도 변화가 K에 미치는 영향을 비교하시오.","passage":null,"answer":"평형에서는 정반응과 역반응이 계속 진행하되 속도가 같아 순변화가 0이므로 농도가 일정하다. 촉매는 평형 도달을 빠르게 하지만 같은 온도의 K를 바꾸지 않는다. 온도 변화는 반응의 열적 성질에 따라 K를 바꿀 수 있다.","wrong":[],"criteria":["동적 평형과 같은 속도","촉매와 K 불변","온도와 K 변화"],"explanation":"","source_label":"Ⅰ-0. 화학평형","source_page":7,"source_slide":null,"source_url":null,"sort":1000},{"id":"chemistry-depth-written-002","deck_id":"chemistry","kind":"written","topic":"평형 실험 · 색 변화와 조작","badge":null,"question":"주황 Cr₂O₇²⁻와 노랑 CrO₄²⁻의 평형에 산·염기를 첨가할 때의 변화를 H⁺와 반응 방향으로 설명하시오.","passage":null,"answer":"Cr₂O₇²⁻+H₂O⇌2CrO₄²⁻+2H⁺에서 산을 넣으면 H⁺가 증가해 역반응으로 주황 이온이 늘어난다. 염기의 OH⁻는 H⁺를 소비하므로 정반응이 유리해져 노랑 이온이 늘어난다. 일정 온도에서 이 농도 조작은 K를 바꾸지 않는다.","wrong":[],"criteria":["산·역반응·주황","OH⁻ 소비·정반응·노랑","일정 온도의 K 유지"],"explanation":"","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":1001},{"id":"chemistry-depth-written-003","deck_id":"chemistry","kind":"written","topic":"평형 실험 · 색 변화와 조작","badge":null,"question":"흡열인 코발트 착물 평형에서 CaCl₂ 첨가·물 희석·가열·냉각의 색 변화와 K 변화 여부를 비교하시오.","passage":null,"answer":"분홍 착물+4Cl⁻⇌파랑 착물+6H₂O에서 CaCl₂ 첨가는 Cl⁻를 늘려 파랑 쪽으로, 물 희석은 이온 농도 감소로 분홍 쪽으로 이동한다. 흡열 정반응이므로 가열은 파랑, 냉각은 분홍 쪽이다. 같은 온도의 첨가·희석은 K를 바꾸지 않고 온도 변화는 K도 바꿀 수 있다.","wrong":[],"criteria":["첨가·희석 색 변화","흡열과 가열·냉각","농도 조작과 온도의 K 차이"],"explanation":"","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":1002},{"id":"chemistry-depth-written-004","deck_id":"chemistry","kind":"written","topic":"산·염기 · 짝과 세기·pH","badge":null,"question":"0.010 M 약산에 대해 x≈0.0030 M을 얻었다. 5% 규칙으로 타당성을 평가하고, 근사가 실패하면 어떤 평형식을 풀어야 하는지 쓰시오.","passage":null,"answer":"이온화율 x/C×100=30%로 5%를 넘으므로 C−x≈C 근사는 부적절하다. 물의 이온화를 무시한다는 조건에서 평형 농도는 HA가 C−x, H₃O⁺와 A⁻가 x이므로 Ka=x²/(C−x)를 이차식으로 풀어 양의 물리적 해를 선택한다.","wrong":[],"criteria":["30% 계산","5% 초과로 근사 부적절","정확한 평형식과 양의 해"],"explanation":"","source_label":"Ⅰ-1,2. 산과염기","source_page":14,"source_slide":null,"source_url":null,"sort":1003},{"id":"chemistry-depth-written-005","deck_id":"chemistry","kind":"written","topic":"중화 반응 · 몰수·희석·혼합","badge":null,"question":"아세트산 시료를 정량 취한 뒤 물을 추가하는 경우와 원액 자체를 희석한 뒤 같은 부피를 취하는 경우, NaOH 적정량이 어떻게 달라지는지 설명하시오.","passage":null,"answer":"정량 취한 시료에 물만 추가하면 산 몰수가 같아 같은 농도 NaOH의 적정량도 같다. 원액 자체를 희석한 뒤 같은 부피를 취하면 단위 부피의 산 몰수가 줄어 필요한 NaOH가 감소한다. 농도 변화와 취한 산의 몰수 변화를 구별해야 한다.","wrong":[],"criteria":["정량 시료 물 추가의 몰수 보존","희석 후 같은 부피의 몰수 감소","농도와 몰수 구별"],"explanation":"","source_label":"Ⅰ-0. 화학 중화반응","source_page":3,"source_slide":null,"source_url":null,"sort":1004},{"id":"chemistry-depth-written-006","deck_id":"chemistry","kind":"written","topic":"적정 실험 · 그래프와 오차","badge":null,"question":"미지 아세트산 20.0 mL에 0.100 M NaOH를 적정했다. 초기 눈금 1.20 mL, 최종 23.20 mL일 때 농도를 계산하고 종말점 초과의 오차 방향을 설명하시오.","passage":null,"answer":"사용량은 23.20−1.20=22.00 mL다. 1:1 반응이므로 아세트산 몰수는 0.100×0.02200=0.002200 mol, 농도는 0.002200/0.0200=0.110 M다. 종말점을 지나 넣은 NaOH까지 사용량으로 잡으면 산 몰수와 농도를 과대 추정한다.","wrong":[],"criteria":["눈금 차 22.00 mL","0.110 M 계산","초과 사용량과 과대 추정"],"explanation":"","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":1005},{"id":"chemistry-depth-written-007","deck_id":"chemistry","kind":"written","topic":"적정 실험 · 그래프와 오차","badge":null,"question":"물에 젖은 피펫·물에 젖은 뷰렛·정량 취한 산이 든 물에 젖은 플라스크의 세 경우가 미지 산 농도 계산에 미치는 영향을 비교하시오.","passage":null,"answer":"산으로 헹구지 않은 피펫 속 물은 취한 산 몰수를 줄여 원액 농도를 과소 추정하게 한다. NaOH로 헹구지 않은 뷰렛 속 물은 표준용액을 희석해 사용량을 늘려 원래 농도로 계산하면 과대 추정한다. 정량 취한 산이 든 플라스크 속 물은 산 몰수를 바꾸지 않아 이상적인 적정 결과에 영향이 없다.","wrong":[],"criteria":["피펫 과소와 몰수 감소","뷰렛 과대와 희석","플라스크 몰수 보존"],"explanation":"","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":1006},{"id":"chemistry-depth-written-008","deck_id":"chemistry","kind":"written","topic":"적정 실험 · 그래프와 오차","badge":null,"question":"적정 곡선을 그릴 때 중화점 부근의 부피 간격, 교반, pH 센서 위치를 어떻게 관리하는지 이유와 함께 설명하시오.","passage":null,"answer":"중화점 부근은 적은 첨가량에도 pH가 크게 변하므로 부피 간격을 작게 한다. NaOH를 넣은 뒤 충분히 저어 국소 농도 차이를 줄이고 센서 응답이 안정된 뒤 기록한다. 센서가 비커 바닥이나 자석 교반기에 닿지 않게 해 파손과 측정 불안정을 줄인다.","wrong":[],"criteria":["중화점 근처 작은 간격","교반·응답 안정","센서 접촉 방지"],"explanation":"","source_label":"실험 정리","source_page":1,"source_slide":null,"source_url":null,"sort":1007},{"id":"chemistry-depth-written-009","deck_id":"chemistry","kind":"written","topic":"염의 가수분해 · 중화점 pH","badge":null,"question":"아세트산·NaOH 적정과 NH₃·HCl 적정의 중화점 pH가 다른 이유를 생성 염과 가수분해 반응으로 설명하시오.","passage":null,"answer":"아세트산·NaOH에서는 CH₃COO⁻가 생겨 CH₃COO⁻+H₂O⇌CH₃COOH+OH⁻로 염기성을 나타낸다. NH₃·HCl에서는 NH₄⁺가 생겨 NH₄⁺+H₂O⇌NH₃+H₃O⁺로 산성을 나타낸다. 중화점은 화학량론적 반응 기준이며 항상 pH 7을 뜻하지 않는다.","wrong":[],"criteria":["아세트산 이온과 OH⁻","암모늄 이온과 H₃O⁺","중화점과 pH 7 구별"],"explanation":"","source_label":"Ⅰ-3. 중화적정","source_page":17,"source_slide":null,"source_url":null,"sort":1008},{"id":"chemistry-depth-written-010","deck_id":"chemistry","kind":"written","topic":"완충 작용 · 원리와 실험 비교","badge":null,"question":"HA와 A⁻가 각각 10 mmol인 완충계에 HCl 2 mmol 또는 NaOH 3 mmol을 따로 넣었다. 각 최종 몰수와 pH 변화 방향을 설명하시오.","passage":null,"answer":"HCl은 A⁻ 2 mmol을 소비해 HA 12 mmol, A⁻ 8 mmol이 되어 pH가 소폭 감소한다. NaOH는 HA 3 mmol을 소비해 HA 7 mmol, A⁻ 13 mmol이 되어 pH가 소폭 증가한다. 완충은 변화가 작다는 뜻이며 pH가 정확히 불변한다는 뜻은 아니다.","wrong":[],"criteria":["산 첨가 후 12·8","염기 첨가 후 7·13","pH 방향과 불변 오해 구별"],"explanation":"","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":1009},{"id":"chemistry-depth-written-011","deck_id":"chemistry","kind":"written","topic":"완충 작용 · 원리와 실험 비교","badge":null,"question":"증류수·아세트산·아세트산 나트륨·두 성분의 혼합물에 산과 염기를 넣어 비교하는 실험을 설계하시오. 통제 조건과 완충 판단 기준을 포함하시오.","passage":null,"answer":"각 용액의 초기 부피와 첨가하는 산·염기의 농도·부피, 온도, 교반과 pH 기록 조건을 같게 한다. 산 첨가군과 염기 첨가군은 별도로 준비해 초기 pH와 첨가 후 안정 pH의 차이를 비교한다. 두 성분이 함께 있는 용액이 두 첨가에서 작은 pH 변화를 보이는지 확인하며 초기 pH 7 여부를 기준으로 삼지 않는다.","wrong":[],"criteria":["동일 부피·첨가량·측정 조건","산·염기 별도 비교","pH 변화량으로 판단"],"explanation":"","source_label":"Ⅰ-5. 완충 작용","source_page":6,"source_slide":null,"source_url":null,"sort":1010},{"id":"chemistry-depth-written-012","deck_id":"chemistry","kind":"written","topic":"계산 심화 · 평형·적정·완충 검산","badge":null,"question":"A⇌B의 K=4인 일정 부피 용기에 A만 1.0 M 넣었다. 초기·변화·평형 농도를 적고 평형 농도를 계산하시오.","passage":null,"answer":"초기 농도는 A=1.0 M, B=0이다. 변화는 A=−x, B=+x이므로 평형 농도는 A=1−x, B=x다. K=x/(1−x)=4에서 x=0.80 M를 얻어 A=0.20 M, B=0.80 M다. 농도 합 1.0 M와 K=4를 다시 확인한다.","wrong":[],"criteria":["초기·변화·평형 기록","K 식과 x 계산","0.20·0.80 M 검산"],"explanation":"","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":1011},{"id":"chemistry-depth-written-013","deck_id":"chemistry","kind":"written","topic":"계산 심화 · 평형·적정·완충 검산","badge":null,"question":"10배 희석한 식초 20 mL에 0.10 M NaOH 16 mL가 중화량이었다. 원액 몰농도와 질량 백분율을 구하시오. 밀도 1.0 g/mL, 아세트산 몰질량 60 g/mol.","passage":null,"answer":"희석액의 산 몰수는 0.10×0.016=0.0016 mol이고 농도는 0.0016/0.020=0.080 M다. 원액은 10배인 0.80 M다. 원액 1 L에 아세트산 48 g이 들어 있고 용액 질량은 1000 g이므로 질량 백분율은 4.8%다.","wrong":[],"criteria":["희석액 0.080 M","원액 0.80 M","밀도 반영 4.8%"],"explanation":"","source_label":"Ⅰ-0. 화학평형","source_page":8,"source_slide":null,"source_url":null,"sort":1012}]$release$::jsonb);
do $$ begin
  if exists (select 1 from expected_science_decks e join public.decks d using(id)
    where (d.subject,d.name,d.full_name,d.teacher,d.description,d.sort)
      is distinct from (e.subject,e.name,e.full_name,e.teacher,e.description,e.sort)) then
    raise exception 'Chemistry deck already exists with different metadata; review before applying';
  end if;
  if exists (select 1 from expected_science_cards e join public.cards c using(id)
    where (c.deck_id,c.kind,c.topic,c.badge,c.question,c.passage,c.answer,c.wrong,c.criteria,c.explanation,c.source_label,c.source_page,c.source_slide,c.source_url,c.sort)
      is distinct from (e.deck_id,e.kind,e.topic,e.badge,e.question,e.passage,e.answer,e.wrong,e.criteria,e.explanation,e.source_label,e.source_page,e.source_slide,e.source_url,e.sort)) then
    raise exception 'New card ID already has different content; review before applying';
  end if;
end $$;
insert into public.decks (id,subject,name,full_name,teacher,description,sort)
select id,subject,name,full_name,teacher,description,sort from expected_science_decks
on conflict(id) do nothing;
insert into public.cards (id,deck_id,kind,topic,badge,question,passage,answer,wrong,criteria,explanation,source_label,source_page,source_slide,source_url,sort)
select id,deck_id,kind,topic,badge,question,passage,answer,wrong,criteria,explanation,source_label,source_page,source_slide,source_url,sort from expected_science_cards
on conflict(id) do nothing;
do $$ begin
  if (select count(*) from expected_science_cards e join public.cards c using(id)) <> 186 then
    raise exception 'Release card count mismatch';
  end if;
end $$;
